const q = {"abstract":[{"id":"abstract-symb-001","f":"single_best","skill":"suite-logique","difficulty":1,"p":"Quel élément complète logiquement cette série ?","s":{"type":"shapes","text":"○  ●  □  ■  △  ?"},"o":["▲","●","◆","△"],"a":0,"e":"Chaque forme apparaît deux fois de suite, d'abord vide puis pleine : cercle, carré, puis triangle. Après △ vient donc ▲.","x":["Correct : le triangle vide est suivi du triangle plein.","Le cercle a déjà été traité au début de la série.","Le losange n'appartient pas à la séquence cercle, carré, triangle.","Répète la figure vide au lieu de passer à sa version pleine."]},{"id":"abstract-arrow-002","f":"single_best","skill":"rotation","difficulty":1,"p":"Quelle paire de flèches complète la suite ?","s":{"type":"shapes","text":"↑ →     ↓ ←     ↑ →     ?"},"o":["↓ ←","→ ↓","← ↑","↑ →"],"a":0,"e":"Chaque paire est la précédente tournée de 180° : ↑ → devient ↓ ←, puis de nouveau ↑ →. La quatrième paire est donc ↓ ←.","x":["Correct : rotation de 180° de la paire ↑ →.","Rotation de 90° seulement.","Rotation de 270° (ou 90° anti-horaire).","Répète la paire sans rotation."]},{"id":"abstract-latin-003","f":"single_best","skill":"matrice","difficulty":1,"p":"Quelle figure remplace le point d'interrogation dans la matrice ?","s":{"type":"shapes","text":"●  ■  ▲\n■  ▲  ●\n▲  ●  ?"},"o":["■","●","▲","□"],"a":0,"e":"Chaque ligne et chaque colonne contient une seule fois le disque, le carré et le triangle, tous pleins. La dernière ligne et la dernière colonne manquent toutes deux du carré plein ■.","x":["Correct : seul figure absente de la ligne et de la colonne.","Le disque figure déjà dans la dernière ligne.","Le triangle figure déjà dans la dernière ligne.","Bonne forme, mais toutes les figures de la matrice sont pleines."]},{"id":"abstract-grid-004","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle case complète la matrice ?","s":{"type":"shapes","text":"●      ○○      ●●●\n■      □□      ■■■\n▲      △△      ?"},"o":["▲▲▲","△△△","▲▲","■■■"],"a":0,"e":"Trois règles : la forme est fixe sur chaque ligne ; le nombre de figures vaut 1, 2 puis 3 selon la colonne ; la colonne du milieu est vide, les autres pleines. Ligne 3, colonne 3 : trois triangles pleins.","x":["Correct : forme, nombre et remplissage respectés.","Le remplissage vide ne vaut que pour la colonne du milieu.","Le nombre doit être 3 dans la dernière colonne.","La forme doit rester le triangle sur la troisième ligne."]},{"id":"abstract-dots-005","f":"single_best","skill":"suite-logique","difficulty":1,"p":"Quel groupe de points complète la progression ?","s":{"type":"shapes","text":"●     ●●     ●●●     ?"},"o":["●●","●●●●","○○○○","●●●●●"],"a":1,"e":"Le nombre de disques pleins augmente d'une unité à chaque étape : 1, 2, 3, puis 4.","x":["Revient en arrière au lieu de progresser.","Correct : quatre disques pleins.","Bon nombre, mais le remplissage change sans raison.","Augmente de deux unités au lieu d'une."]},{"id":"abstract-rot-006","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle figure vient ensuite dans la série ?","s":{"type":"shapes","text":"◰  →  ◳  →  ◲  →  ?"},"o":["◱","◰","◳","◲"],"a":0,"e":"Le quadrant marqué tourne d'un quart de tour dans le sens horaire : haut-gauche, haut-droite, bas-droite, puis bas-gauche (◱).","x":["Correct : quadrant bas-gauche après bas-droite.","Revient au point de départ, une étape trop tôt.","Rotation dans le sens inverse.","Répète la dernière figure."]},{"id":"abstract-interleave-007","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel élément complète la série ?","s":{"type":"shapes","text":"●    ▲    ●●    ▲▲    ●●●    ?"},"o":["▲▲▲","●●●●","▲▲","▲▲▲▲"],"a":0,"e":"Deux suites alternent : les disques (1, 2, 3) et les triangles (1, 2, …). Le sixième terme appartient à la suite des triangles, qui passe à 3.","x":["Correct : troisième terme de la suite des triangles.","Prolonge la suite des disques au mauvais rang.","Répète le terme précédent de la suite des triangles.","Saute une étape de la progression."]},{"id":"abstract-flip-008","f":"single_best","skill":"transformation","difficulty":2,"p":"La même transformation s'applique à chaque paire. Quelle figure remplace le point d'interrogation ?","s":{"type":"shapes","text":"▲  →  ▽\n◀  →  ▷\n▼  →  ?"},"o":["△","▽","▲","◁"],"a":0,"e":"Les deux exemples montrent la même transformation : un demi-tour (180°) et l'inversion du remplissage. Seul le demi-tour explique à la fois ▲ → ▽ et ◀ → ▷ (une symétrie selon un seul axe ne marche que pour l'un des deux). ▼ tourné de 180° donne ▲, puis vide : △.","x":["Correct : demi-tour puis remplissage inversé.","Remplissage inversé, mais sans demi-tour.","Demi-tour, mais remplissage conservé.","Mauvaise orientation : la figure ne pointe ni vers le haut ni vers le bas."]},{"id":"abstract-mirror-009","f":"single_best","skill":"transformation","difficulty":3,"p":"Appliquez la même règle à la seconde ligne. Quel résultat obtient-on ?","s":{"type":"shapes","text":"●  ■  ▲   →   △  □  ○\n◆  ○  ■   →   ?"},"o":["□  ●  ◇","■  ○  ◆","◇  ●  □","□  ○  ◇"],"a":0,"e":"Deux règles combinées : l'ordre des figures est inversé, et chaque remplissage est inversé. ◆ ○ ■ inversé donne ■ ○ ◆, puis le remplissage inversé donne □ ● ◇.","x":["Correct : ordre inversé et remplissage inversé.","Ordre inversé, mais remplissage conservé.","Remplissage inversé, mais ordre conservé.","Le disque n'a pas été inversé."]},{"id":"abstract-gap-010","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel élément complète la série ?","s":{"type":"shapes","text":"●  ■  ●  ■  ■  ●  ■  ■  ■  ?"},"o":["●","■","▲","○"],"a":0,"e":"Entre deux disques, le nombre de carrés augmente : 1, 2, puis 3. Après le troisième carré du groupe de trois vient donc un disque.","x":["Correct : le groupe de trois carrés est complet.","Un quatrième carré dépasserait le groupe de trois.","Le triangle n'apparaît pas dans la série.","Le disque est plein dans toute la série."]},{"id":"abstract-matrix-011","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle case complète logiquement la troisième ligne de cette matrice ?","s":{"type":"shapes","text":"●       ■       ▲\n■■      ▲▲      ●●\n▲▲▲     ●●●     ?"},"o":["■■■","▲▲▲","●●●","□□□"],"a":0,"e":"Deux règles combinées s'appliquent : d'une part, chaque ligne permute les trois formes de base (cercle, carré, triangle) ; d'autre part, le nombre de symboles augmente de 1 par ligne (1 en ligne 1, 2 en ligne 2, 3 en ligne 3). La case manquante doit donc contenir 3 carrés pleins (■■■).","x":["Correct : forme carrée requise pour compléter le triplet (triangle, disque, carré) avec 3 éléments pleins.","Le triangle figure déjà en première case de la troisième ligne.","Le disque figure déjà en deuxième case de la troisième ligne.","Forme correcte mais vide, alors que toutes les figures de la matrice sont pleines."]},{"id":"abstract-clock-012","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle flèche poursuit logiquement la rotation ?","s":{"type":"shapes","text":"↑  →  ↗  →  →  →  ↘  →  ?"},"o":["↓","↙","←","↑"],"a":0,"e":"La flèche effectue une rotation continue de 45° dans le sens horaire à chaque pas : nord (↑), nord-est (↗), est (→), sud-est (↘). L'étape suivante pointe donc plein sud (↓).","x":["Correct : rotation horaire de 45° après le point cardinal sud-est (↘).","Rotation de 90° au lieu de 45° après le sud-est.","Rotation de 135° sautant deux étapes d'orientation.","Retour erroné au point de départ de la séquence."]},{"id":"abstract-pair-013","f":"single_best","skill":"transformation","difficulty":2,"p":"La même règle s'applique à chaque couple. Quelle paire remplace le point d'interrogation ?","s":{"type":"shapes","text":"● ○   →   ○ ●\n■ □   →   □ ■\n▲ △   →   ?"},"o":["△ ▲","▲ △","△ △","▲ ▲"],"a":0,"e":"Chaque paire subit une permutation horizontale de ses deux composantes : le symbole plein à gauche passe à droite, et le symbole vide à droite passe à gauche. ▲ △ devient donc △ ▲.","x":["Correct : permutation de la figure pleine et de la figure vide.","Identique à la figure initiale sans appliquer la permutation.","Deux figures vides au lieu d'une permutation.","Deux figures pleines au lieu d'une permutation."]},{"id":"abstract-step-014","f":"single_best","skill":"suite-logique","difficulty":3,"p":"Quel groupe de symboles complète cette double progression ?","s":{"type":"shapes","text":"◆◆◆◆    ◇    ◆◆◆    ◇◇    ◆◆    ◇◇◇    ?"},"o":["◆","◇◇◇◇","◆◆","◇◇"],"a":0,"e":"Deux progressions entrelacées alternent : les termes impairs présentent des losanges pleins décroissants (4, 3, 2, puis 1), tandis que les termes pairs présentent des losanges vides croissants (1, 2, 3). Le 7e terme est impair et doit donc comporter un seul losange plein (◆).","x":["Correct : la suite des losanges pleins décroît (4, 3, 2, 1) au 7e terme.","Prolonge la suite des losanges vides qui n'intervient qu'au rang suivant.","Répète le terme précédent des losanges pleins sans décrémentation.","Régression injustifiée dans la suite des losanges vides."]},{"id":"abstract-diag-015","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle figure complète logiquement la matrice 2×2 ci-dessous ?","s":{"type":"shapes","text":"◀   ▶\n▲   ?"},"o":["▼","▲","◀","▶"],"a":0,"e":"La première ligne associe deux triangles horizontaux de directions opposées (◀ et ▶, soit un retournement à 180°). La seconde ligne applique la même relation d'opposition aux triangles verticaux : ▲ opposé donne ▼.","x":["Correct : symétrie axiale inversant l'orientation (gauche/droite en ligne 1, haut/bas en ligne 2).","Répétition sans inversion d'orientation.","Réintroduction d'une orientation horizontale sur une ligne verticale.","Orientation vers la droite sans rapport avec l'axe vertical de la seconde ligne."]},{"id":"abstract-symb-016","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel symbole complète logiquement cette série de figures ?","s":{"type":"shapes","text":"●  ▲  ■  ●  ▲  ▲  ■  ■  ●  ▲  ▲  ▲  ?"},"o":["■■■","▲▲▲","●●","■■"],"a":0,"e":"La série est rythmée par un disque isolateur ● suivi de triangles puis de carrés en nombre croissant : d'abord 1▲ et 1■, puis 2▲ et 2■, enfin 3▲ et donc 3■.","x":["Correct : les triangles et carrés augmentent de 1 à chaque cycle (1▲ 1■, 2▲ 2■, 3▲ 3■).","Le groupe de 3 triangles vient d'être achevé, c'est au tour des carrés.","Le disque reste un séparateur isolé unique à chaque cycle.","Deux carrés correspondent au cycle précédent, le cycle actuel en exige 3."]},{"id":"abstract-matrix-017","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle case complète la dernière ligne de la matrice 3×3 ?","s":{"type":"shapes","text":"○   △   □\n●   ▲   ■\n◎   ◬   ?"},"o":["回","■","□","◇"],"a":0,"e":"Chaque colonne conserve une forme géométrique : colonne 1 = cercle, colonne 2 = triangle, colonne 3 = carré. Chaque ligne applique un traitement : ligne 1 = forme simple vide, ligne 2 = forme pleine, ligne 3 = forme concentrique imbriquée.","x":["Correct : cercle concentrique, triangle imbriqué, puis carré avec cadre concentrique (figure double).","Le carré plein figure déjà sur la deuxième ligne.","Le carré simple vide figure déjà sur la première ligne.","Le losange n'appartient pas à la famille cercle-triangle-carré de la matrice."]},{"id":"abstract-rot-018","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle figure succède logiquement dans la séquence rotative ?","s":{"type":"shapes","text":"▲  →  ▶  →  ▼  →  ?"},"o":["◀","▲","▶","▼"],"a":0,"e":"Le triangle tourne de 90° dans le sens horaire à chaque pas : haut (▲), droite (▶), bas (▼), puis gauche (◀).","x":["Correct : rotation horaire de 90° faisant pointer le sommet vers la gauche.","Retour en arrière de 270° au lieu d'une rotation de 90°.","Répétition de la deuxième étape sans progression.","Répétition de l'étape précédente."]},{"id":"abstract-trans-019","f":"single_best","skill":"transformation","difficulty":2,"p":"Quelle figure remplace le point d'interrogation selon la même relation ?","s":{"type":"shapes","text":"◐  →  ◑\n◓  →  ?"},"o":["◒","◓","◐","◑"],"a":0,"e":"La première ligne effectue une symétrie inversant le côté plein (gauche devient droite). La seconde ligne applique la même inversion à la division horizontale : le demi-disque haut plein (◓) devient le demi-disque bas plein (◒).","x":["Correct : demi-disque haut plein devenant demi-disque bas plein par symétrie axiale.","Figure identique sans transformation.","Passe arbitrairement à une division verticale.","Confusion avec la transformation de la première ligne."]},{"id":"abstract-matrix-020","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle figure complète la matrice 2×2 ci-dessous ?","s":{"type":"shapes","text":"◆   ◇\n●   ?"},"o":["○","●","◆","◇"],"a":0,"e":"Chaque ligne conserve sa forme propre (losange en ligne 1, disque en ligne 2) et passe de la version pleine à la version vide de gauche à droite. ● donne donc ○.","x":["Correct : la forme pleine devient vide (◆ donne ◇, donc ● donne ○).","Conserve le remplissage plein sans appliquer la règle de la première ligne.","Réintroduit le losange sur la ligne des disques.","Réintroduit le losange vide déjà présent en ligne 1."]},{"id":"abstract-step-021","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel terme complète logiquement cette progression arithmétique de formes ?","s":{"type":"shapes","text":"★     ★★     ★★★     ?"},"o":["★★★★","★★★","★★★★★","☆☆☆☆"],"a":0,"e":"La règle est une incrémentation constante d'une étoile pleine par étape. Après 3 étoiles pleines viennent 4 étoiles pleines (★★★★).","x":["Correct : progression de +1 étoile pleine à chaque étape (1, 2, 3, 4).","Répète le terme précédent sans incrémenter.","Saute une étape en passant directement à 5 étoiles.","Bonne quantité mais altère arbitrairement le remplissage en étoiles vides."]},{"id":"abstract-rot-022","f":"single_best","skill":"rotation","difficulty":3,"p":"Quelle figure poursuit cette rotation anti-horaire ?","s":{"type":"shapes","text":"◳  →  ◰  →  ◱  →  ?"},"o":["◲","◳","◰","◱"],"a":0,"e":"Le quadrant plein effectue une rotation de 90° dans le sens anti-horaire : haut-droite (◳), haut-gauche (◰), bas-gauche (◱), puis bas-droite (◲).","x":["Correct : le quadrant plein passe de bas-gauche (◱) à bas-droite (◲) en sens anti-horaire.","Retour erroné au point initial avant d'avoir bouclé le cycle.","Rotation dans le sens inverse (horaire).","Répétition de la figure précédente."]},{"id":"abstract-trans-023","f":"single_best","skill":"transformation","difficulty":2,"p":"Quelle figure correspond à la même règle de symétrie horizontale ?","s":{"type":"shapes","text":"◁  →  ▷\n▲  →  ▲\n◀  →  ?"},"o":["▶","◀","▲","▼"],"a":0,"e":"La transformation est un retournement horizontal (miroir vertical). Le triangle plein orienté vers la gauche (◀) devient un triangle plein orienté vers la droite (▶).","x":["Correct : triangle plein orienté vers la gauche tourné en triangle plein orienté vers la droite.","Figure identique sans symétrie.","Orientation verticale sans rapport avec la symétrie horizontale.","Orientation vers le bas sans rapport avec la règle gauche/droite."]},{"id":"abstract-matrix-024","f":"single_best","skill":"matrice","difficulty":3,"p":"Quelle case remplace le point d'interrogation dans la matrice 3×3 ?","s":{"type":"shapes","text":"●  ■  ▲\n▲  ●  ■\n■  ▲  ?"},"o":["●","■","▲","○"],"a":0,"e":"Il s'agit d'un carré latin de formes : chaque ligne et colonne permute le cercle, le carré et le triangle. La troisième ligne (■, ▲, ?) et la troisième colonne (▲, ■, ?) manquent toutes deux du cercle plein ●.","x":["Correct : chaque ligne et chaque colonne comporte exactement un cercle, un carré et un triangle pleins.","Le carré est déjà présent en première colonne de la troisième ligne.","Le triangle est déjà présent en deuxième colonne de la troisième ligne.","La forme circulaire est correcte mais elle doit être pleine comme le reste de la matrice."]},{"id":"abstract-symb-025","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel groupe de figures complète logiquement la série alternée ?","s":{"type":"shapes","text":"○ ●     ○○ ●●     ○○○ ●●●     ?"},"o":["○○○○ ●●●●","○○○○ ●●●","○○○ ●●●●","●●●● ○○○○"],"a":0,"e":"Chaque groupe contient un nombre égal de cercles vides puis pleins, avec un incrément d'une unité à chaque étape : 1, 2, 3, puis 4. Le terme suivant comporte 4 disques vides suivis de 4 disques pleins.","x":["Correct : les cercles vides et les cercles pleins progressent simultanément de 1 à chaque pas (4 de chaque).","Sous-estime le nombre de disques pleins qui doit égaler 4.","Omet d'incrémenter le groupe des disques vides.","Inverse l'ordre d'apparition en plaçant les disques pleins avant les vides."]},{"id":"abstract-rot-026","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle flèche complète la rotation continue de 90° anti-horaire ?","s":{"type":"shapes","text":"↑  →  ←  →  ↓  →  ?"},"o":["→","↑","←","↓"],"a":0,"e":"La flèche tourne de 90° dans le sens anti-horaire (trigonométrique) : nord (↑), ouest (←), sud (↓), puis est (→).","x":["Correct : après sud (↓), la rotation anti-horaire de 90° pointe vers l'est (→).","Rotation de 180° au lieu de 90°.","Retour en arrière vers l'ouest.","Répétition de l'orientation sud précédente."]},{"id":"abstract-matrix-027","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle case complète la dernière colonne de la matrice ?","s":{"type":"shapes","text":"◆      ◆◆      ◆◆◆\n◇      ◇◇      ?"},"o":["◇◇◇","◇◇","◆◆◆","◇◇◇◇"],"a":0,"e":"Chaque ligne conserve sa forme propre (losanges pleins en ligne 1, vides en ligne 2). Chaque colonne augmente la quantité d'une unité : 1 en colonne 1, 2 en colonne 2, 3 en colonne 3. Ligne 2, colonne 3 requiert donc 3 losanges vides (◇◇◇).","x":["Correct : 3 losanges vides, prolongeant la progression 1, 2, 3 en ligne 2.","Répète la case précédente sans progression.","Introduit des losanges pleins réservés à la première ligne.","Progresse de 2 unités au lieu d'une."]},{"id":"abstract-trans-028","f":"single_best","skill":"transformation","difficulty":3,"p":"Quelle figure résulte de la combinaison des deux transformations ?","s":{"type":"shapes","text":"■ ▲   →   ▲ ■ (inversion position)\n▲ △   →   △ ▲ (inversion position)\n● ○   →   ?"},"o":["○ ●","● ○","● ●","○ ○"],"a":0,"e":"La transformation permute strictement la figure de gauche et la figure de droite : ● ○ devient donc ○ ●.","x":["Correct : permutation horizontale inversant la place du disque plein et du disque vide.","Identique sans permutation.","Deux figures pleines au lieu d'une inversion de position.","Deux figures vides au lieu d'une inversion de position."]},{"id":"abstract-symb-029","f":"single_best","skill":"suite-logique","difficulty":3,"p":"Quel terme complète cette suite alternée à double pas ?","s":{"type":"shapes","text":"●  ■  ■  ●  ■  ■  ■  ●  ■  ■  ■  ■  ?"},"o":["●","■","▲","○"],"a":0,"e":"Entre deux disques pleins ●, le nombre de carrés pleins ■ augmente d'un à chaque intervalle : 2 carrés, puis 3 carrés, puis 4 carrés. Le groupe de 4 étant achevé, le terme suivant est un disque ●.","x":["Correct : le bloc de 4 carrés est terminé, un disque délimiteur s'impose.","Ajouterait un cinquième carré rompant le cycle de 4.","Forme triangulaire étrangère à la suite.","Cercle vide alors que tous les cercles de la série sont pleins."]},{"id":"abstract-rot-030","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle orientation prend la flèche après 3 rotations successives de 45° horaire ?","s":{"type":"shapes","text":"←  →  ↖  →  ↑  →  ?"},"o":["↗","→","↓","↘"],"a":0,"e":"La flèche tourne régulièrement de 45° dans le sens horaire : ouest (←), nord-ouest (↖), nord (↑). L'orientation suivante pointe au nord-est (↗).","x":["Correct : rotation de 45° horaire après le nord (↑) amenant la flèche au nord-est (↗).","Rotation de 90° au lieu de 45° après le nord.","Rotation de 180° opposée au nord.","Rotation de 135° sautant une orientation."]},{"id":"abstract-matrix-031","f":"single_best","skill":"matrice","difficulty":3,"p":"Quelle forme remplace le point d'interrogation dans la matrice 3×3 ?","s":{"type":"shapes","text":"△  △  △\n□  □  □\n○  ○  ?"},"o":["○","●","□","△"],"a":0,"e":"La règle horizontale impose l'invariance stricte de forme et de remplissage sur chaque ligne : ligne 1 = triangles vides, ligne 2 = carrés vides, ligne 3 = cercles vides. La case manquante est donc un cercle vide (○).","x":["Correct : chaque ligne conserve une forme identique sur ses trois cases (cercles vides en ligne 3).","Cercle plein alors que toutes les figures de la matrice sont vides.","Le carré appartient exclusivement à la deuxième ligne.","Le triangle appartient exclusivement à la première ligne."]},{"id":"abstract-trans-032","f":"single_best","skill":"transformation","difficulty":2,"p":"Quelle figure complète la transformation par inversion de remplissage ?","s":{"type":"shapes","text":"■  →  □\n●  →  ○\n◆  →  ?"},"o":["◇","◆","□","○"],"a":0,"e":"Chaque forme pleine devient sa contrepartie vide correspondante : le losange plein ◆ devient un losange vide ◇.","x":["Correct : inversion de remplissage transformant le losange plein en losange vide.","Conserve le remplissage plein sans transformation.","Remplace arbitrairement la forme par un carré.","Remplace arbitrairement la forme par un cercle."]},{"id":"abstract-symb-033","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel symbole complète la suite décroissante de formes ?","s":{"type":"shapes","text":"■■■■■  →  ■■■■  →  ■■■  →  ■■  →  ?"},"o":["■","□","■■■","●"],"a":0,"e":"Le nombre de carrés pleins décroît d'une unité à chaque étape : 5, 4, 3, 2, puis 1 carré plein (■).","x":["Correct : décrémentation constante de 1 carré plein (5, 4, 3, 2, 1).","Carré vide alors que tous les éléments de la suite sont pleins.","Remonte à 3 carrés au lieu de poursuivre la décrémentation.","Changement injustifié de forme géométrique."]},{"id":"abstract-rot-034","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle figure complète la demi-rotation (180°) ?","s":{"type":"shapes","text":"▲  →  ▼\n◀  →  ▷\n↑  →  ?"},"o":["↓","↑","→","←"],"a":0,"e":"Chaque terme subit un demi-tour complet (180°) : haut devient bas, gauche devient droite. La flèche pointant vers le haut (↑) pointe donc vers le bas (↓).","x":["Correct : rotation de 180° inversant la direction du nord (↑) vers le sud (↓).","Figure identique sans rotation.","Rotation de 90° horaire au lieu de 180°.","Rotation de 90° anti-horaire au lieu de 180°."]},{"id":"abstract-matrix-035","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle figure complète logiquement la matrice 2×2 ?","s":{"type":"shapes","text":"●   ▲\n■   ?"},"o":["◆","●","▲","■"],"a":0,"e":"La matrice associe 4 polygones de complexité ou forme différente sans répétition (cercle, triangle, carré, losange). La case manquante est le losange plein ◆.","x":["Correct : quatrième figure géométrique distincte complétant l'ensemble (cercle, triangle, carré, losange).","Répète le cercle figurant déjà en première case.","Répète le triangle figurant déjà en deuxième case.","Répète le carré figurant déjà en troisième case."]}],"verbal":[{"id":"verbal-deduct-001","f":"single_best","skill":"inference","difficulty":1,"p":"Quelle conclusion est absolument certaine à partir des seuls éléments fournis ?","s":"Tous les dossiers urgents sont examinés le jour même. Le dossier L est urgent.","o":["Le dossier L est accepté.","Le dossier L est examiné le jour même.","Le dossier L est le premier examiné.","Tous les dossiers de la journée sont urgents."],"a":1,"e":"L'énoncé affirme expressément que tout dossier urgent fait l'objet d'un examen le jour même ; aucune conclusion sur la décision finale ou l'ordre exact n'est permise.","x":["L'examen ne préjuge en rien de la décision finale (acceptation ou rejet).","Correct : tout dossier urgent étant examiné le jour même, le dossier L l'est obligatoirement.","L'énoncé ne précise aucun ordre de passage parmi les dossiers examinés.","Généralise abusivement la propriété d'un sous-ensemble à l'ensemble des dossiers."]},{"id":"verbal-cond-002","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle affirmation découle rigoureusement des conditions indiquées ?","s":"Le guichet ouvre à 8 h 30. Les rendez-vous avant 10 h sont réservés aux demandes déjà complètes. Nora a obtenu un rendez-vous à 9 h 15.","o":["La demande de Nora est déjà complète.","Nora sera reçue avant l'ouverture générale du guichet.","Nora sera reçue dès l'ouverture du guichet.","La demande de Nora sera automatiquement acceptée."],"a":0,"e":"Les créneaux avant 10 h sont réservés aux demandes déjà complètes ; un rendez-vous à 9 h 15 implique donc une demande complète. Le texte ne dit rien de l'heure exacte de passage, ni de la décision.","x":["Correct : les créneaux avant 10 h étant réservés aux dossiers complets, un créneau à 9 h 15 implique un dossier complet.","Le guichet ouvrant à 8 h 30, un rendez-vous à 9 h 15 a lieu après l'ouverture.","L'ouverture a lieu à 8 h 30, tandis que le rendez-vous de Nora est calé à 9 h 15.","L'obtention d'un rendez-vous ne préjuge aucunement de l'acceptation de la demande."]},{"id":"verbal-quant-003","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : Malik travaille à distance.","s":"Certains analystes travaillent à distance. Malik est analyste.","o":["Vrai","Faux","On ne peut pas savoir"],"a":2,"e":"L'expression « certains » indique l'existence d'au moins un analyste à distance, sans préciser si Malik en fait partie.","x":["Généralise « certains » à tous les analystes.","Le texte n'exclut pas non plus que Malik travaille à distance.","Correct : « certains » ne permet pas de savoir si Malik en fait partie."]},{"id":"verbal-order-004","f":"single_best","skill":"application-consigne","difficulty":1,"p":"Quelle séquence respecte scrupuleusement la règle de classement ?","s":"Classer les dossiers par date croissante. À date identique, placer en premier le numéro le plus petit.","o":["12/04 n° 18, puis 11/04 n° 22","11/04 n° 22, puis 11/04 n° 19","11/04 n° 19, puis 11/04 n° 22","12/04 n° 12, puis 11/04 n° 10"],"a":2,"e":"À date identique (11/04), le numéro le plus faible (19) doit impérativement précéder le numéro plus élevé (22).","x":["Viole la préséance de date croissante (le 12/04 est placé avant le 11/04).","À date identique (11/04), le numéro le plus faible (19) doit impérativement précéder le 22.","Correct : date identique (11/04) et ordre croissant strict des numéros (19 avant 22).","Viole l'ordre chronologique croissant des dates."]},{"id":"verbal-neg-005","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle conclusion n'est PAS justifiée par le passage ?","s":"Aucun rapport incomplet n'est transmis. Certains rapports du service B sont transmis.","o":["Certains rapports du service B sont complets.","Aucun rapport transmis n'est incomplet.","Tous les rapports du service B sont transmis.","Au moins un rapport du service B est transmis."],"a":2,"e":"Le passage mentionne que certains rapports sont transmis, ce qui interdit d'affirmer que tous les rapports du service le sont.","x":["Justifié : les rapports transmis étant nécessairement complets, ceux de B qui sont transmis sont complets.","Justifié : découle directement de la prémisse interdisant la transmission de rapports incomplets.","Correct : le fait que certains rapports soient transmis n'autorise pas à affirmer que tous le sont.","Justifié : l'emploi de « certains » implique l'existence d'au moins un élément."]},{"id":"verbal-syll-006","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle déduction s'impose logiquement à partir des deux prémisses ?","s":"Tout arrêté ministériel fait l'objet d'une publication. Le document G ne fait l'objet d'aucune publication.","o":["Le document G n'est pas un arrêté ministériel.","Le document G est un projet de loi en cours.","Le document G sera publié ultérieurement.","Certains arrêtés ministériels ne sont pas publiés."],"a":0,"e":"Par contraposition logique : si tout arrêté est publié, un document non publié ne peut en aucun cas constituer un arrêté ministériel.","x":["Correct : par contraposition (si arrêté alors publié ; non publié donc pas un arrêté).","Spéculation sans fondement dans les prémisses fournies.","Supposition temporelle non étayée par le texte.","Contredit formellement la règle selon laquelle tout arrêté est publié."]},{"id":"verbal-rule-007","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quelle décision est conforme à la directive énoncée ?","s":"Toute demande de subvention supérieure à 50 000 euros requiert un avis préalable de la commission financière. Le projet Alpha sollicite 45 000 euros.","o":["Le projet Alpha ne requiert pas obligatoirement l'avis préalable de la commission financière au titre de cette règle.","Le projet Alpha doit impérativement obtenir l'accord unanime de la commission financière.","Le projet Alpha sera automatiquement rejeté pour insuffisance de montant.","Le projet Alpha est dispensé de tout contrôle administratif."],"a":0,"e":"Le seuil obligatoire est fixé strictement aux montants supérieurs à 50 000 euros ; 45 000 euros ne déclenchent pas cette obligation spécifique.","x":["Correct : le seuil d'exigence étant strictement supérieur à 50 000 euros, 45 000 euros n'activent pas cette obligation.","La règle n'évoque aucun accord unanime requis.","Confusion : la directive n'impose aucun seuil minimal pour solliciter une subvention.","Généralisation abusive : le projet n'est exempté que de cette formalité spécifique."]},{"id":"verbal-extrap-008","f":"single_best","skill":"inference","difficulty":3,"p":"Laquelle des propositions constitue une extrapolation non démontrée par le texte ?","s":"La dématérialisation des formulaires a réduit le délai moyen de traitement de 14 jours à 6 jours au premier semestre.","o":["Les usagers sont globalement plus satisfaits de la qualité de service.","Le délai moyen de traitement constaté s'est contracté de 8 jours.","Le délai moyen est passé sous la barre des dix jours au premier semestre.","Le traitement moyen était plus long avant le premier semestre concerné."],"a":0,"e":"Le texte renseigne un indicateur temporel précis (délai en jours), mais ne fournit aucune donnée sur le niveau de satisfaction des usagers.","x":["Correct : le texte n'apporte aucune donnée sur la satisfaction des usagers, seulement un indicateur de délai.","Parfaitement démontré par la différence arithmétique (14 - 6 = 8 jours).","Démontré par l'observation directe du chiffre de 6 jours.","Démontré par la comparaison avec la durée préalable de 14 jours."]},{"id":"verbal-equiv-009","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle formulation exprime exactement le même sens logique ?","s":"Il est impossible d'accéder à la zone sécurisée sans badge d'identification actif.","o":["Avoir un badge actif est une condition indispensable pour accéder à la zone sécurisée.","Toute personne munie d'un badge actif a le droit d'entrer dans la zone sécurisée.","Les personnes sans badge peuvent être admises avec un accompagnateur.","Le badge actif garantit un accès permanent et sans restriction."],"a":0,"e":"L'absence de badge empêchant l'accès, la détention d'un badge actif constitue bien une condition nécessaire (indispensable) d'accès.","x":["Correct : l'impossibilité d'accéder sans badge fait de sa détention une condition nécessaire (indispensable).","Confond condition nécessaire et condition suffisante (le badge est requis, mais d'autres conditions peuvent s'appliquer).","Extrapole une exception d'accompagnement non stipulée dans la règle.","Le badge est requis, mais il ne confère aucun accès permanent ou sans restriction."]},{"id":"verbal-fact-010","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle proposition relève d'un fait constatable et non d'une appréciation subjective ?","s":"Le nouveau logiciel de gestion des congés est remarquable, il enregistre 1 200 connexions quotidiennes et simplifie grandement la vie du personnel.","o":["Le logiciel enregistre 1 200 connexions quotidiennes.","Le nouveau logiciel est particulièrement remarquable.","La vie du personnel est grandement simplifiée.","Ce système est la meilleure solution disponible."],"a":0,"e":"Le comptage de 1 200 connexions est une mesure quantitative objectivement vérifiable, à la différence des appréciations qualitatives.","x":["Correct : le comptage de 1 200 connexions est une donnée objective et quantifiable.","Appréciation qualitative subjective.","Jugement de valeur subjectif quant au bien-être du personnel.","Jugement subjectif sans fondement factuel quantifié."]},{"id":"verbal-telework-011","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quelle décision est strictement conforme à la directive de service ?","s":"Toute demande de télétravail occasionnel doit être déposée au moins 5 jours ouvrés à l'avance auprès de la hiérarchie. Par exception, en cas d'intempéries majeures constatées par un avis officiel, le délai est réduit à 24 heures. L'agent Laurent dépose sa demande 3 jours ouvrés avant la date souhaitée, en l'absence de tout avis officiel d'intempéries.","o":["La demande de Laurent ne respecte pas le délai réglementaire exigé.","La demande de Laurent est automatiquement validée par défaut.","Laurent peut bénéficier de la dérogation réduite à 24 heures.","Le délai de 5 jours ouvrés ne s'applique qu'au télétravail régulier."],"a":0,"e":"La directive impose un préavis de 5 jours ouvrés pour le télétravail occasionnel. L'unique dérogation (24 heures) requiert un avis officiel d'intempéries. En l'absence d'un tel avis, la demande déposée à 3 jours ouvrés viole le délai réglementaire.","x":["Correct : en l'absence d'avis officiel d'intempéries, le délai obligatoire de 5 jours ouvrés s'applique.","Le texte ne mentionne aucun mécanisme d'accord tacite ou d'approbation automatique.","L'exception de 24 heures est expressément conditionnée à un avis officiel d'intempéries.","La directive précise explicitement qu'elle régit le télétravail occasionnel."]},{"id":"verbal-tfcs-012","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : Tous les candidats retenus pour l'épreuve orale ont validé l'évaluation écrite.","s":"Seuls les candidats ayant validé l'évaluation écrite avec une note minimale de 12 sur 20 sont convoqués à l'épreuve orale. Vingt-cinq candidats participent actuellement à l'épreuve orale.","o":["Vrai","Faux","On ne peut pas savoir"],"a":0,"e":"L'emploi de la tournure restrictive « seuls les candidats ayant validé l'évaluation écrite... » établit que la validation écrite est une condition sine qua non. Tout candidat présent à l'oral l'a donc obligatoirement validée.","x":["Correct : la validation de l'évaluation écrite est une condition nécessaire stricte d'accès à l'oral.","Contredit formellement la règle d'admission énoncée dans le texte.","Le texte est affirmatif et sans ambiguïté sur cette condition exclusive (« seuls les candidats... »)."]},{"id":"verbal-synth-013","f":"single_best","skill":"synthese","difficulty":2,"p":"Quelle proposition résume le plus fidèlement le champ d'application de la note ?","s":"Le présent guide de gestion s'applique à l'ensemble des agents titulaires et stagiaires de l'administration centrale. Les collaborateurs externes et prestataires sont soumis exclusivement aux clauses de leur contrat spécifique, à l'exception des consignes de sécurité des bâtiments qui s'imposent à toute personne présente dans les locaux.","o":["Le guide régit titulaires et stagiaires, tandis que seules les consignes de sécurité s'imposent universellement.","Le guide de gestion s'applique intégralement aux collaborateurs externes et prestataires de services.","Les agents stagiaires bénéficient d'un régime d'exception identique à celui des prestataires.","Les consignes de sécurité des bâtiments ne concernent que les agents sous contrat de droit public."],"a":0,"e":"Le passage opère une distinction claire : les agents publics (titulaires et stagiaires) relèvent du guide, les prestataires relèvent de leur contrat, et les consignes de sécurité s'appliquent indistinctement à tous.","x":["Correct : résume fidèlement le champ d'application interne et l'universalité de la seule sécurité.","En contradiction avec le texte qui restreint les prestataires à leur contrat.","Faux : les stagiaires sont au contraire inclus dans le champ général avec les titulaires.","Faux : le texte précise que la sécurité s'impose à toute personne présente dans les locaux."]},{"id":"verbal-deont-014","f":"single_best","skill":"inference","difficulty":3,"p":"Quelle déduction s'impose logiquement par contraposition ?","s":"Tout fonctionnaire participant à une commission de sélection doit souscrire une déclaration préalable d'absence de conflit d'intérêts. L'agent Marc n'a souscrit aucune déclaration d'absence de conflit d'intérêts.","o":["L'agent Marc ne peut pas régulièrement participer à une commission de sélection.","L'agent Marc est sous le coup d'une procédure disciplinaire pour omission.","L'agent Marc participera à la commission de sélection avec une dispense écrite.","Certains fonctionnaires sont dispensés de déclaration en commission de sélection."],"a":0,"e":"La règle énonce une implication universelle : Participation ⇒ Déclaration. Par contraposition logique (Non Déclaration ⇒ Non Participation), Marc ne peut légalement siéger en commission de sélection.","x":["Correct : contraposition stricte (si participation alors déclaration ; or pas de déclaration donc pas de participation régulière).","Extrapolation injustifiée : le texte n'évoque aucune sanction disciplinaire.","Contredit la règle selon laquelle tout fonctionnaire participant doit déclarer.","Contredit le caractère universel de l'obligation énoncée (« tout fonctionnaire »)."]},{"id":"verbal-cert-015","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle affirmation est directement corroborée par les faits mentionnés ?","s":"La nouvelle procédure de délivrance numérique a permis de délivrer 4 500 attestations au premier trimestre, contre 3 000 attestations papier au trimestre correspondant de l'année précédente.","o":["Le volume d'attestations délivrées a augmenté de 1 500 unités entre les deux trimestres comparés.","La procédure numérique a totalement supprimé les erreurs de saisie des agents.","Les usagers préfèrent unanimement le format numérique au format papier.","Toutes les attestations administratives de l'État sont désormais délivrées en ligne."],"a":0,"e":"Seule la hausse factuelle de 1 500 attestations (4 500 contre 3 000) découle directement du texte. Les autres options constituent des jugements subjectifs ou des généralisations sans preuve.","x":["Correct : corroboré par la différence arithmétique directe (4 500 - 3 000 = 1 500).","Extrapolation infondée : le texte ne mentionne aucun taux d'erreur.","Jugement qualitatif subjectif absent des données factuelles du texte.","Généralisation abusive à l'ensemble des attestations administratives de l'État."]},{"id":"verbal-contra-016","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle conclusion s'impose avec une certitude absolue à partir des prémisses fournies ?","s":"Tout marché public d'un montant supérieur à 100 000 euros requiert un avis préalable du contrôleur financier. L'acquisition de matériel X n'a reçu aucun avis du contrôleur financier.","o":["Le montant du marché X n'est pas supérieur à 100 000 euros.","Le marché X est entaché d'une nullité administrative définitive.","Le contrôleur financier a refusé de valider le marché X.","Le marché X sera examiné lors de la prochaine session financière."],"a":0,"e":"Par application directe de la contraposée logique : si la règle impose « Marché > 100 000 € ⇒ Avis », alors l'absence d'avis implique nécessairement que le marché ne dépasse pas ce seuil réglementaire sous réserve de conformité.","x":["Correct : par contraposition stricte (si montant > 100 000 € alors avis obligatoire ; or pas d'avis, donc montant ≤ 100 000 € pour être régulier).","Extrapolation infondée : le texte ne statue sur aucune nullité prononcée.","Affirmation non étayée : l'absence d'avis ne prouve pas un refus d'examen.","Pure supposition temporelle sans ancrage dans le texte fourni."]},{"id":"verbal-tfcs-017","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : L'agent Claire a droit au remboursement intégral de ses frais de déplacement.","s":"Les agents effectuant un déplacement professionnel hors du Grand-Duché bénéficient d'une indemnité forfaitaire kilométrique. Claire a effectué un déplacement professionnel à Esch-sur-Alzette.","o":["Vrai","Faux","On ne peut pas savoir"],"a":2,"e":"Le texte ne mentionne que les conditions applicables aux déplacements internationaux. Rien n'est précisé sur les modalités applicables aux déplacements à l'intérieur du Grand-Duché (comme Esch-sur-Alzette). Il est impossible de conclure.","x":["Le texte ne précise pas si les déplacements nationaux sont remboursés ou exclus.","Le texte n'affirme pas que les déplacements nationaux sont privés de remboursement.","Correct : la règle régit les déplacements hors du pays, mais reste silencieuse sur les règles applicables aux trajets nationaux comme Esch-sur-Alzette."]},{"id":"verbal-rule-018","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quelle décision applique rigoureusement la consigne de conservation ?","s":"Les procès-verbaux de séance sont versés aux archives définitives après un délai de 5 ans en archives courantes. Les brouillons préparatoires doivent être détruits immédiatement après adoption du texte définitif.","o":["Détruire les brouillons préparatoires dès l'adoption du texte définitif.","Conserver les brouillons préparatoires pendant une durée minimale de 5 ans.","Verser les brouillons préparatoires aux archives définitives avec le procès-verbal.","Transférer les procès-verbaux aux archives définitives dès leur adoption."],"a":0,"e":"La consigne distingue formellement les procès-verbaux (conservés 5 ans en archives courantes avant versement) et les brouillons préparatoires (destruction immédiate obligatoire dès adoption).","x":["Correct : respecte scrupuleusement l'obligation de destruction immédiate des brouillons.","Confond la règle des brouillons avec le délai de conservation des procès-verbaux.","Viole l'obligation de destruction en conservant des documents préparatoires.","Viole le délai intermédiaire de 5 ans imposé pour les procès-verbaux."]},{"id":"verbal-quant-019","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle déduction logique est nécessairement vraie ?","s":"Aucun document non signé n'est exécutoire. Certains documents de la division R sont exécutoires.","o":["Certains documents de la division R sont signés.","Tous les documents de la division R sont signés.","Aucun document de la division R n'est signé.","Tous les documents signés sont exécutoires."],"a":0,"e":"Si aucun document non signé n'est exécutoire, tout document exécutoire est obligatoirement signé. Comme certains documents de la division R sont exécutoires, ils sont donc nécessairement signés.","x":["Correct : les documents exécutoires étant obligatoirement signés, ceux de la division R qui sont exécutoires sont signés.","Généralisation abusive : seuls certains documents de R sont exécutoires.","Contredit directement la prémisse affirmant que certains documents de R sont exécutoires.","Confond condition nécessaire (signature requise) et condition suffisante."]},{"id":"verbal-comp-020","f":"single_best","skill":"comprehension","difficulty":1,"p":"Quelle proposition énonce un fait objectif et non une appréciation qualitative ?","s":"La refonte du portail citoyen a permis de diviser par deux le délai de délivrance des extraits de casier judiciaire, passant de 6 jours à 3 jours ouvrés, pour le plus grand confort des administrés.","o":["Le délai de délivrance est passé de 6 jours à 3 jours ouvrés.","Le confort des administrés est grandement amélioré par la réforme.","La nouvelle procédure est la plus efficace de l'administration.","Le portail citoyen offre une ergonomie particulièrement réussie."],"a":0,"e":"Le passage de 6 à 3 jours ouvrés est une donnée temporelle chiffrée, mesurable et vérifiable, contrairement aux mentions sur le confort ou la qualité ergonomique.","x":["Correct : mesure chiffrée factuelle, vérifiable et exempte de jugement de valeur.","Appréciation qualitative subjective sur le ressenti des usagers.","Jugement de valeur comparatif sans base quantitative fournie.","Opinion esthétique et ergonomique subjective."]},{"id":"verbal-synth-021","f":"single_best","skill":"synthese","difficulty":2,"p":"Quelle proposition résume le plus fidèlement le dispositif décrit ?","s":"Les demandes de subvention sont recevables du 1er janvier au 31 mars. Toute demande déposée hors délai est déclarée irrecevable sans examen au fond, sauf cas de force majeure dûment attesté par une autorité publique compétente.","o":["Les demandes hors délai sont irrecevables, sauf force majeure attestée par une autorité.","Toute demande déposée après le 31 mars est définitivement rejetée sans exception possible.","Les demandes déposées entre janvier et mars font l'objet d'une acceptation automatique.","Une attestation sur l'honneur suffit pour justifier un dépôt de dossier tardif."],"a":0,"e":"La synthèse exacte préserve la règle générale (irrecevabilité des dossiers tardifs) ainsi que sa condition dérogatoire stricte (force majeure établie par une autorité publique).","x":["Correct : reprend fidèlement le principe d'irrecevabilité et l'unique exception d'autorité.","Ignore l'exception expresse de force majeure prévue par le texte.","Confond la recevabilité de la demande avec son acceptation au fond.","Contredit l'exigence d'une attestation délivrée par une autorité publique compétente."]},{"id":"verbal-tfcs-022","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : La demande de congé de Julien a été approuvée par son supérieur.","s":"Toute demande de congé bonifié doit être déposée un mois avant le départ. Julien a déposé sa demande de congé bonifié six semaines avant la date de départ prévue.","o":["Vrai","Faux","On ne peut pas savoir"],"a":2,"e":"Le texte confirme uniquement le respect de la formalité temporelle de dépôt (6 semaines > 1 mois requis). Il ne contient aucune information quant à l'acceptation ou au refus de la demande.","x":["Le respect du délai de dépôt ne garantit pas la décision favorable de l'autorité.","Le texte n'indique en aucun cas que la demande de Julien a été refusée.","Correct : Julien a respecté le délai de dépôt, mais le texte ne dit rien sur la décision finale de sa hiérarchie."]},{"id":"verbal-syll-023","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle proposition est rigoureusement déduite des prémisses ?","s":"Tous les inspecteurs assermentés disposent d'un droit d'accès aux locaux professionnels. Aucun stagiaire n'est assermenté.","o":["Certaines personnes ayant un droit d'accès ne sont pas stagiaires.","Tous les stagiaires sont interdits d'accès aux locaux professionnels.","Tous les inspecteurs assermentés sont d'anciens stagiaires.","L'assermentation est accordée à tout agent après deux ans de service."],"a":0,"e":"Les inspecteurs assermentés ont un droit d'accès et aucun stagiaire n'est assermenté. Par conséquent, les inspecteurs assermentés représentent au moins une catégorie de personnes dotées d'un droit d'accès qui ne sont pas des stagiaires.","x":["Correct : les inspecteurs assermentés disposent du droit d'accès et, n'étant pas stagiaires, constituent des personnes autorisées non-stagiaires.","Le texte ne dit pas que les stagiaires ne peuvent pas avoir accès pour un autre motif.","Spéculation sur l'historique de carrière absente du texte.","Règle temporelle totalement inexistante dans les prémisses."]},{"id":"verbal-app-024","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quel dossier remplit scrupuleusement toutes les conditions d'éligibilité ?","s":"Pour être éligible au fonds d'innovation, un projet doit réunir trois critères cumulatifs : être porté par au moins deux services distincts, avoir une durée d'exécution inférieure à 12 mois, et ne pas dépasser un budget total de 50 000 euros.","o":["Projet A : 2 services, durée de 9 mois, budget de 45 000 euros.","Projet B : 1 service, durée de 6 mois, budget de 30 000 euros.","Projet C : 3 services, durée de 14 mois, budget de 48 000 euros.","Projet D : 2 services, durée de 10 mois, budget de 55 000 euros."],"a":0,"e":"Seul le projet A remplit simultanément les trois conditions cumulatives imposées par le texte : au moins deux services (2), durée inférieure à 12 mois (9 mois), et budget n'excédant pas 50 000 euros (45 000 euros).","x":["Correct : 2 services (≥ 2), 9 mois (< 12) et 45 000 € (≤ 50 000 €) valident les 3 critères cumulatifs.","Échoue sur le nombre de services (1 seul service au lieu de deux au minimum).","Échoue sur la durée d'exécution (14 mois dépasse la limite stricte de 12 mois).","Échoue sur le budget prévisionnel (55 000 € dépasse le plafond de 50 000 €)."]},{"id":"verbal-comp-025","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle proposition reformule le texte sans altérer son sens logique ?","s":"Le renouvellement d'une autorisation d'exploitation n'est accordé que si l'exploitant a transmis son bilan environnemental annuel avant le 1er décembre.","o":["La transmission du bilan avant le 1er décembre est une condition nécessaire au renouvellement.","La transmission du bilan avant le 1er décembre garantit automatiquement le renouvellement.","L'exploitant qui transmet son bilan le 5 décembre obtiendra une dérogation de plein droit.","Le renouvellement de l'autorisation d'exploitation dispense du bilan environnemental."],"a":0,"e":"La formulation « n'est accordé que si » signifie que sans ce dépôt préalable avant le 1er décembre, le renouvellement est impossible. Cela en fait une condition sine qua non (nécessaire), mais pas forcément suffisante.","x":["Correct : la locution « n'est accordé que si » définit strictement une condition nécessaire.","Confond condition nécessaire et condition suffisante d'approbation.","Contredit formellement l'échéance impérative du 1er décembre.","Contredit l'obligation légale de transmission du bilan."]},{"id":"verbal-inf-026","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle conclusion est absolument certaine ?","s":"Toutes les réunions de crise ont lieu dans la salle rouge. La réunion de ce matin a lieu dans la salle bleue.","o":["La réunion de ce matin n'est pas une réunion de crise.","La réunion de ce matin est un simple point d'information interne.","La salle rouge était indisponible ce matin pour travaux.","Aucune réunion n'a eu lieu dans la salle rouge ce matin."],"a":0,"e":"Si toute réunion de crise se déroule obligatoirement dans la salle rouge, une réunion tenue dans la salle bleue ne peut en aucun cas être une réunion de crise (contraposition formelle).","x":["Correct : par contraposition (si réunion de crise alors salle rouge ; or salle bleue, donc pas de crise).","Spéculation sur la nature exacte de la réunion non étayée par le texte.","Hypothèse matérielle non mentionnée dans les prémisses.","Rien ne permet d'affirmer que la salle rouge est restée inoccupée."]},{"id":"verbal-tfcs-027","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : L'ensemble des fonctionnaires du ministère a suivi la session de sensibilisation à la cybersécurité.","s":"La participation à la session de sensibilisation à la cybersécurité était obligatoire pour les agents du service informatique. Certains agents d'autres services y ont également assisté de manière volontaire.","o":["Vrai","Faux","On ne peut pas savoir"],"a":1,"e":"Le texte stipule que la session n'était obligatoire que pour le service informatique et que seuls certains agents des autres départements étaient présents. L'affirmation selon laquelle « l'ensemble » des fonctionnaires y a assisté est donc fausse.","x":["Affirmer que tous ont suivi la session contredit le périmètre restreint d'obligation du texte.","Correct : l'obligation ne visait que le service informatique et seuls certains agents des autres services ont participé, ce qui exclut une participation universelle.","Le texte permet d'affirmer avec certitude que la totalité n'y a pas participé."]},{"id":"verbal-app-028","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quelle modalité de transmission est strictement conforme à la directive ?","s":"Les réclamations relatives à la taxe foncière doivent être transmises exclusivement par pli recommandé avec avis de réception ou déposées contre récépissé au secrétariat communal.","o":["Envoi postal par lettre recommandée avec avis de réception.","Transmission par courrier électronique avec confirmation de lecture.","Dépôt d'une lettre simple dans la boîte aux lettres de la commune.","Appel téléphonique enregistré auprès de l'agent de permanence."],"a":0,"e":"La consigne restreint les voies de recours admissibles à deux modalités exclusives : le pli recommandé avec accusé de réception ou le dépôt physique contre récépissé. L'envoi en recommandé AR est donc conforme.","x":["Correct : mode d'envoi expressément prévu et autorisé par la directive.","L'envoi électronique n'est pas autorisé par l'adverbe d'exclusivité « exclusivement ».","Le dépôt sans récépissé ne remplit pas l'exigence formelle requise.","La voie orale par téléphone est dépourvue de toute valeur probante au regard de la règle."]},{"id":"verbal-inf-029","f":"single_best","skill":"inference","difficulty":3,"p":"Laquelle des assertions constitue une extrapolation non garantie par le passage ?","s":"Au cours de l'année écoulée, l'introduction d'un outil d'indexation automatisé a permis aux agents d'instruire 1 800 requêtes contre 1 200 l'année précédente, sans augmentation d'effectif.","o":["Les agents éprouvent une plus grande satisfaction dans leur quotidien professionnel.","Le nombre total de requêtes instruites a progressé de 50 % par rapport à l'année précédente.","L'effectif du service est demeuré stable sur les deux années comparées.","La productivité moyenne par agent a augmenté au cours de l'année écoulée."],"a":0,"e":"Le texte ne fournit que des indicateurs quantitatifs objectifs (volume de dossiers et stabilité des ressources humaines). Prêter aux agents une satisfaction accrue relève d'une extrapolation subjective non garantie.","x":["Correct : le passage renseigne des données d'activité et d'effectif, mais aucune indication sur la satisfaction des agents.","Démontré mathématiquement : (1 800 - 1 200) / 1 200 = 600 / 1 200 = +50 %.","Démontré textuellement par la mention « sans augmentation d'effectif ».","Démontré par la hausse de volume à effectif inchangé."]},{"id":"verbal-synth-030","f":"single_best","skill":"synthese","difficulty":2,"p":"Quelle proposition synthétise le plus fidèlement les obligations déontologiques énoncées ?","s":"Tout fonctionnaire est tenu au secret professionnel pour les faits dont il a connaissance dans l'exercice de ses fonctions. Il ne peut en être délié que par une décision expresse du ministre de tutelle ou dans les cas expressément prescrits par la loi pénale.","o":["Le secret s'impose à tout fonctionnaire, avec pour seules dérogations la décision ministérielle ou la loi pénale.","Le fonctionnaire peut librement divulguer des informations réservées à ses collègues proches.","La levée du secret professionnel est accordée de plein droit sur simple demande d'un citoyen.","Le secret professionnel ne s'applique plus dès lors que l'agent quitte définitivement son service."],"a":0,"e":"La synthèse restitue fidèlement les deux composantes du texte : le caractère général de l'obligation de secret professionnel et les deux seuls cas d'exception limitativement énumérés (décision du ministre ou prescription de la loi pénale).","x":["Correct : résume fidèlement le champ universel de l'obligation et les deux seules exceptions limitatives.","Viole l'obligation de secret qui ne tolère aucun partage informel entre collègues.","Contredit le principe d'interdiction et les conditions strictes de levée.","Extrapolation injustifiée : l'obligation demeure attachée aux faits connus en exercice."]},{"id":"verbal-inf-031","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle déduction logique est incontestable ?","s":"Tous les lauréats de l'épreuve A1 possèdent un diplôme de niveau master ou équivalent. Marc est lauréat de l'épreuve A1.","o":["Marc possède un diplôme de niveau master ou équivalent.","Marc est déjà titularisé dans son grade de recrutement.","Marc a obtenu la note maximale lors de l'épreuve écrite.","Tous les titulaires d'un master réussissent l'épreuve A1."],"a":0,"e":"Puisque l'ensemble des lauréats possède un diplôme de niveau master ou équivalent et que Marc appartient à cet ensemble, Marc détient nécessairement ce niveau de qualification.","x":["Correct : déduction directe par syllogisme (Tout A est B ; Marc est A ; donc Marc est B).","Confusion entre le statut de lauréat et la titularisation ultérieure.","Spéculation sur la note obtenue sans base dans l'énoncé.","Réciproque erronée (affirmer que tout master réussit inverse l'implication logique)."]},{"id":"verbal-app-032","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quelle suite convient de donner selon la directive interne ?","s":"En cas d'absence imprévue pour raison de santé, l'agent doit en informer sa hiérarchie dans un délai de 2 heures suivant sa prise de service théorique, et transmettre un certificat médical sous 48 heures ouvrables.","o":["Prévenir sa hiérarchie sous 2 heures et envoyer le certificat médical sous 48 heures ouvrables.","Attendre 48 heures ouvrables avant d'établir le premier contact avec son service.","Déposer un certificat médical sans obligation préalable d'information hiérarchique.","Prévenir sa hiérarchie uniquement après avoir obtenu son certificat médical."],"a":0,"e":"La règle cumule deux obligations temporelles précises : un avertissement hiérarchique rapide (sous 2 heures) puis la formalisation justificative par certificat (sous 48 heures ouvrables).","x":["Correct : respecte scrupuleusement les deux démarches et leurs délais respectifs distincts.","Omet l'obligation de premier signalement dans les 2 heures.","Viole l'exigence d'information immédiate sous 2 heures.","Inverse la chronologie des obligations fixée par la directive."]},{"id":"verbal-tfcs-033","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : Le dossier de subvention n° 404 sera automatiquement rejeté.","s":"Les dossiers de subvention incomplets sont retournés au demandeur avec un délai de régularisation de 15 jours calendaires. Le dossier n° 404 déposé par l'association E est incomplet.","o":["Vrai","Faux","On ne peut pas savoir"],"a":1,"e":"Le texte stipule expressément que les dossiers incomplets ne sont pas rejetés directement, mais renvoyés pour régularisation sous 15 jours. L'affirmation d'un rejet automatique est donc fausse.","x":["Le texte ne prévoit pas de rejet automatique, mais un retour pour régularisation sous 15 jours.","Correct : le dossier incomplet n'est pas rejeté d'emblée, il bénéficie d'une procédure de régularisation.","La règle de traitement des dossiers incomplets est clairement et explicitement définie dans le texte."]},{"id":"verbal-comp-034","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle proposition exprime la même restriction d'accès ?","s":"Seuls les agents titulaires d'une habilitation de sécurité spéciale peuvent consulter les documents classifiés de niveau 3.","o":["L'habilitation de sécurité spéciale est indispensable pour consulter ces documents.","Tout agent titulaire de l'habilitation spéciale a obligation de consulter ces documents.","Les agents stagiaires peuvent consulter ces documents s'ils sont accompagnés d'un tuteur.","L'habilitation de sécurité spéciale dispense de tout contrôle de sécurité ultérieur."],"a":0,"e":"La locution restrictive « seuls les agents... peuvent » établit que détenir l'habilitation constitue une condition nécessaire et incontournable (indispensable) pour consulter les documents classifiés.","x":["Correct : la restriction « seuls les agents titulaires » fait de l'habilitation une condition sine qua non.","Confond autorisation d'accès avec obligation professionnelle de consultation.","Extrapole une exception de tutorat non prévue par le texte.","Rien n'indique que l'habilitation dispense de respecter les règles de sécurité."]},{"id":"verbal-inf-035","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle conclusion découle avec certitude des éléments fournis ?","s":"Certains membres de la commission d'évaluation sont experts-comptables. Tous les experts-comptables sont soumis à un code de déontologie financière.","o":["Certains membres de la commission d'évaluation sont soumis à un code de déontologie financière.","Tous les membres de la commission d'évaluation sont soumis à un code de déontologie financière.","Aucun membre de la commission d'évaluation n'est expert-comptable.","La commission d'évaluation est composée exclusivement d'experts-comptables."],"a":0,"e":"Puisque certains membres de la commission sont experts-comptables et que tout expert-comptable relève du code de déontologie, il existe obligatoirement des membres de la commission soumis à ce code.","x":["Correct : les membres qui sont experts-comptables étant tous soumis au code, certains membres le sont obligatoirement.","Généralisation abusive à l'ensemble des membres de la commission.","Contredit formellement la première prémisse.","L'adjectif « certains » interdit d'affirmer l'exclusivité de la composition."]}],"numeric":[{"id":"numeric-ratio-001","f":"single_best","skill":"variation","difficulty":2,"p":"Quel service administratif enregistre la plus forte progression relative entre janvier et février ?","s":{"type":"table","caption":"Demandes traitées par service","headers":["Service","Janvier","Février"],"rows":[["A",120,138],["B",80,96],["C",150,165]]},"o":["Service A","Service B","Service C","Service A et Service B à égalité"],"a":1,"e":"Calcul des taux : Service A = (138-120)/120 = +15 % ; Service B = (96-80)/80 = +20 % ; Service C = (165-150)/150 = +10 %. Le service B a la plus forte hausse.","x":["Le service A progresse de (138 - 120) / 120 = +15 %.","Correct : le service B progresse de (96 - 80) / 80 = +20 %, soit la hausse relative la plus forte.","Le service C progresse de (165 - 150) / 150 = +10 %.","Les progressions relatives sont différentes : 15 % pour A et 20 % pour B."]},{"id":"numeric-mean-002","f":"single_best","skill":"moyenne","difficulty":1,"p":"Combien de dossiers sont instruits en moyenne chaque jour ouvré ?","s":"Une équipe instruit 420 dossiers en 7 jours ouvrés à rythme régulier et constant.","o":["50 dossiers","55 dossiers","60 dossiers","65 dossiers"],"a":2,"e":"Le calcul direct de la moyenne quotidienne donne 420 divisé par 7, soit exactement 60 dossiers par jour ouvré.","x":["Sous-estime la cadence quotidienne (50 × 7 = 350 dossiers au lieu de 420).","Erreur de division arithmétique (55 × 7 = 385 dossiers).","Correct : 420 dossiers divisés par 7 jours ouvrés donnent 60 dossiers par jour.","Surestime la cadence quotidienne (65 × 7 = 455 dossiers)."]},{"id":"numeric-perc-003","f":"single_best","skill":"pourcentage","difficulty":1,"p":"Quel est le nouveau temps moyen de réponse après optimisation ?","s":"Un temps moyen de réponse de 40 minutes est réduit de 15 % grâce à une procédure simplifiée.","o":["34 minutes","35 minutes","36 minutes","38 minutes"],"a":0,"e":"La réduction s'élève à 15 % de 40 = 6 minutes. Le nouveau délai est donc de 40 - 6 = 34 minutes.","x":["Correct : réduction de 15 % de 40 min = 6 min ; 40 - 6 = 34 minutes.","Soustraction erronée de 5 minutes au lieu de 6 minutes.","Correspondrait à une réduction de 10 % seulement (4 minutes retranchées).","Correspondrait à une réduction de 5 % seulement (2 minutes retranchées)."]},{"id":"numeric-rate-004","f":"single_best","skill":"pourcentage","difficulty":1,"p":"Combien de demandes reçoivent une décision favorable ?","s":"Sur un total de 250 demandes d'agrément examinées, 72 % sont approuvées.","o":["170 demandes","175 demandes","180 demandes","185 demandes"],"a":2,"e":"Le calcul direct donne 250 × 0,72 = 180 demandes approuvées.","x":["Correspondrait à 68 % de 250 demandes.","Correspondrait à 70 % de 250 demandes.","Correct : 250 × 0,72 = 180 demandes approuvées.","Correspondrait à 74 % de 250 demandes."]},{"id":"numeric-table-005","f":"single_best","skill":"lecture-tableau","difficulty":2,"p":"Quel trimestre présente le taux de résolution le plus performant ?","s":{"type":"table","caption":"Demandes par trimestre","headers":["Trimestre","Reçues","Résolues"],"rows":[["T1",200,160],["T2",240,204],["T3",180,144]]},"o":["Trimestre 1","Trimestre 2","Trimestre 3","Trimestre 1 et Trimestre 3 à égalité"],"a":1,"e":"Taux de résolution : T1 = 160/200 = 80 % ; T2 = 204/240 = 85 % ; T3 = 144/180 = 80 %. Le trimestre 2 est le plus performant.","x":["T1 affiche un taux de 160 / 200 = 80 %.","Correct : T2 affiche un taux de 204 / 240 = 85 %, le plus performant.","T3 affiche un taux de 144 / 180 = 80 %.","T1 et T3 atteignent tous deux 80 %, mais restent inférieurs aux 85 % de T2."]},{"id":"numeric-budget-006","f":"single_best","skill":"pourcentage","difficulty":2,"p":"Quel montant résiduel reste-t-il disponible sur l'enveloppe allouée ?","s":"Une enveloppe budgétaire de 80 000 euros est consommée à hauteur de 45 % au premier trimestre, puis 25 % du budget initial au second trimestre.","o":["24 000 euros","20 000 euros","28 000 euros","16 000 euros"],"a":0,"e":"La consommation totale représente 45 % + 25 % = 70 % du montant initial. La part restante est de 30 % de 80 000 euros, soit 24 000 euros.","x":["Correct : consommation cumulée de 70 % ; reste 30 % de 80 000 € = 24 000 euros.","Correspondrait à 25 % de reliquat (75 % de consommation supposée).","Sous-estimerait la consommation globale à 65 % au lieu de 70 %.","Calculerait seulement 20 % de budget résiduel."]},{"id":"numeric-weight-007","f":"single_best","skill":"moyenne","difficulty":2,"p":"Quelle est la moyenne pondérée des trois évaluations ?","s":"Évaluation A (coefficient 3) : 14/20. Évaluation B (coefficient 2) : 16/20. Évaluation C (coefficient 5) : 11/20.","o":["12,9 / 20","13,2 / 20","13,7 / 20","12,5 / 20"],"a":0,"e":"Calcul de la moyenne pondérée : [(14×3) + (16×2) + (11×5)] / (3+2+5) = (42 + 32 + 55) / 10 = 129 / 10 = 12,9 / 20.","x":["Correct : [(14×3) + (16×2) + (11×5)] / 10 = (42 + 32 + 55) / 10 = 129 / 10 = 12,9.","Erreur d'application sur la pondération du coefficient 5.","Correspondrait à la moyenne simple non pondérée : (14 + 16 + 11) / 3 = 13,67.","Sous-évaluation globale résultant d'une erreur de sommation des coefficients."]},{"id":"numeric-scale-008","f":"single_best","skill":"ratio-proportion","difficulty":2,"p":"Quelle est la distance réelle sur le terrain correspondant à cette mesure ?","s":"Sur un plan d'urbanisme à l'échelle 1:2 500, un tracé de raccordement mesure 8 centimètres.","o":["200 mètres","20 mètres","2 000 mètres","160 mètres"],"a":0,"e":"La distance réelle équivaut à 8 cm × 2 500 = 20 000 cm = 200 mètres.","x":["Correct : 8 cm × 2 500 = 20 000 cm = 200 mètres.","Erreur d'un facteur 10 dans la conversion des centimètres en mètres.","Erreur d'un facteur 10 par excès dans la conversion d'unités.","Confusion dans le calcul (8 × 2 000 au lieu de 8 × 2 500)."]},{"id":"numeric-speed-009","f":"single_best","skill":"operations-simples","difficulty":3,"p":"Combien de temps faut-il pour traiter les 60 dossiers restants en travaillant conjointement ?","s":"L'agent X traite 6 dossiers par heure. L'agent Y traite 4 dossiers par heure.","o":["6 heures","5 heures","7 heures","8 heures"],"a":0,"e":"Leur cadence combinée est de 6 + 4 = 10 dossiers par heure. Pour 60 dossiers, il faut 60 / 10 = 6 heures.","x":["Correct : cadence cumulée de 6 + 4 = 10 dossiers/h ; 60 / 10 = 6 heures.","Sous-estime le temps nécessaire (à 10 dossiers/h, 5 h ne produiraient que 50 dossiers).","Surestimerait la durée nécessaire en minorant le débit conjoint.","Correspondrait au travail d'un seul agent sans mise en commun des cadences."]},{"id":"numeric-delta-010","f":"single_best","skill":"variation","difficulty":2,"p":"De combien de points de pourcentage le taux de présence a-t-il augmenté ?","s":"Le taux de participation des agents aux formations passe de 60 % à 75 % d'une année sur l'autre.","o":["15 points","25 points","15 %","20 points"],"a":0,"e":"La différence entre deux pourcentages s'exprime en points de pourcentage : 75 - 60 = 15 points (alors que la hausse relative est de 25 %).","x":["Correct : l'écart arithmétique absolu entre 75 % et 60 % est de 15 points de pourcentage.","Confond la progression relative (+25 %) avec l'écart absolu en points.","Emploie le symbole % réservé aux variations relatives, et non aux points d'écart.","Erreur arithmétique dans la soustraction 75 - 60."]},{"id":"numeric-table-011","f":"single_best","skill":"lecture-tableau","difficulty":2,"p":"Quel est le montant total des dépenses engagées pour la Direction B sur l'ensemble de l'exercice ?","s":{"type":"table","caption":"Dépenses trimestrielles par direction (en milliers d'euros)","headers":["Direction","Semestre 1","Semestre 2"],"rows":[["Direction A",320,380],["Direction B",240,260],["Direction C",180,220]],"note":"Crédits consommés arrêtés au 31 décembre."},"o":["500 milliers d'euros","480 milliers d'euros","520 milliers d'euros","700 milliers d'euros"],"a":0,"e":"La Direction B a consommé 240 milliers d'euros au premier semestre et 260 milliers d'euros au second semestre. La somme annuelle totale est de 240 + 260 = 500 milliers d'euros (soit 500 000 euros).","x":["Correct : addition des deux semestres de la Direction B : 240 + 260 = 500 milliers d'euros.","Correspondrait à la somme de Direction C (180 + 220 = 400) plus une erreur de calcul.","Erreur d'addition sur le deuxième semestre.","Correspond au total de la Direction A (320 + 380 = 700 milliers d'euros)."]},{"id":"numeric-ratio-012","f":"single_best","skill":"ratio-proportion","difficulty":2,"p":"Quel montant revient au Projet Sud selon la clé de répartition convenue ?","s":"Une dotation régionale de 90 000 euros est partagée entre le Projet Nord et le Projet Sud selon un ratio de 2 pour 3 (2 parts pour Nord, 3 parts pour Sud).","o":["54 000 euros","36 000 euros","45 000 euros","60 000 euros"],"a":0,"e":"Le nombre total de parts est de 2 + 3 = 5 parts. La valeur d'une part s'élève à 90 000 / 5 = 18 000 euros. Le Projet Sud disposant de 3 parts, il reçoit 3 × 18 000 = 54 000 euros.","x":["Correct : 3 parts sur 5 au total : 90 000 × (3 / 5) = 54 000 euros.","Correspond à la part du Projet Nord (2 parts sur 5 : 90 000 × 2 / 5 = 36 000 euros).","Correspondrait à un partage égalitaire 1 pour 1 (90 000 / 2).","Calcul erroné basé sur les deux tiers directs de l'enveloppe globale."]},{"id":"numeric-perc-013","f":"single_best","skill":"pourcentage","difficulty":3,"p":"Quel est le montant final de la subvention après ces deux évolutions successives ?","s":"Une subvention initiale de 50 000 euros augmente de 10 % la première année, puis diminue de 10 % l'année suivante.","o":["49 500 euros","50 000 euros","49 000 euros","51 000 euros"],"a":0,"e":"La première année, la subvention atteint 50 000 × 1,10 = 55 000 euros. La seconde année, la baisse de 10 % s'applique à cette nouvelle base : 55 000 × 0,90 = 49 500 euros (perte nette de 1 % par rapport au montant de départ).","x":["Correct : 50 000 × 1,10 = 55 000 €, puis 55 000 × 0,90 = 49 500 euros.","Erreur classique consistant à croire qu'une hausse de 10 % annule une baisse de 10 %.","Soustraction forfaitaire erronée de 1 000 euros.","Application inversée des pourcentages conduisant à une surévaluation."]},{"id":"numeric-mean-014","f":"single_best","skill":"moyenne","difficulty":2,"p":"Quel est le coût moyen de traitement par dossier sur l'ensemble des dossiers instruits ?","s":"Le bureau 1 traite 100 dossiers pour un coût moyen de 20 euros par dossier. Le bureau 2 traite 300 dossiers pour un coût moyen de 40 euros par dossier.","o":["35 euros","30 euros","32 euros","38 euros"],"a":0,"e":"Le coût total est de (100 × 20 €) + (300 × 40 €) = 2 000 € + 12 000 € = 14 000 €. Le nombre total de dossiers étant de 100 + 300 = 400, le coût moyen pondéré est de 14 000 / 400 = 35 euros.","x":["Correct : coût global = (100 × 20) + (300 × 40) = 2 000 + 12 000 = 14 000 € ; 14 000 / 400 = 35 euros.","Moyenne arithmétique simple erronée sans pondération : (20 + 40) / 2 = 30 euros.","Sous-pondération arbitraire du bureau 2.","Surpondération excessive du bureau 2."]},{"id":"numeric-var-015","f":"single_best","skill":"variation","difficulty":2,"p":"Quel est le pourcentage de variation du nombre de visites entre le premier et le second semestre ?","s":"Le portail administratif enregistre 8 000 visites au premier semestre et 10 000 visites au second semestre.","o":["+25,0 %","+20,0 %","+2 000 %","+15,0 %"],"a":0,"e":"Le taux d'évolution se calcule selon la formule (Valeur finale - Valeur initiale) / Valeur initiale : (10 000 - 8 000) / 8 000 = 2 000 / 8 000 = 0,25, soit une progression de +25,0 %.","x":["Correct : variation relative = (10 000 - 8 000) / 8 000 = 2 000 / 8 000 = +25,0 %.","Erreur de dénominateur : division par la valeur finale 10 000 au lieu de la base 8 000.","Confusion entre la valeur absolue de l'augmentation (+2 000) et le pourcentage.","Sous-estimation arbitraire du ratio de croissance."]},{"id":"numeric-calc-016","f":"single_best","skill":"pourcentage","difficulty":2,"p":"Quel est le montant de la remise totale accordée sur cette commande de fournitures ?","s":"Un marché de fournitures administratives d'un montant brut de 12 000 euros bénéficie d'une remise commerciale de 8 %.","o":["960 euros","800 euros","1 040 euros","1 200 euros"],"a":0,"e":"Le montant de la remise se calcule directement : 12 000 € × (8 / 100) = 960 euros.","x":["Correct : 12 000 × 0,08 = 960 euros.","Calcul basé sur un taux erroné de 6,67 %.","Surestimation correspondant à un taux de 8,67 %.","Correspondrait à une remise de 10 % au lieu de 8 %."]},{"id":"numeric-table-017","f":"single_best","skill":"lecture-tableau","difficulty":2,"p":"Quel département affiche le taux de conformité le plus élevé ?","s":{"type":"table","caption":"Contrôles de conformité par département","headers":["Département","Dossiers contrôlés","Dossiers conformes"],"rows":[["Département Nord",200,170],["Département Sud",250,220],["Département Centre",150,126]]},"o":["Département Sud","Département Nord","Département Centre","Département Nord et Centre à égalité"],"a":0,"e":"Taux de conformité respectifs : Nord = 170 / 200 = 85,0 % ; Sud = 220 / 250 = 88,0 % ; Centre = 126 / 150 = 84,0 %. Le Département Sud présente le taux le plus élevé.","x":["Correct : 220 / 250 = 88,0 %, taux le plus élevé du tableau.","Département Nord : 170 / 200 = 85,0 %.","Département Centre : 126 / 150 = 84,0 %.","Les taux de Nord (85 %) et Centre (84 %) sont distincts et inférieurs à Sud."]},{"id":"numeric-var-018","f":"single_best","skill":"variation","difficulty":2,"p":"Quelle est la variation relative des inscriptions entre 2024 et 2025 ?","s":"Le nombre d'inscriptions à l'examen professionnel est passé de 400 candidats en 2024 à 460 candidats en 2025.","o":["+15,0 %","+12,0 %","+60,0 %","+13,0 %"],"a":0,"e":"La variation relative est donnée par (Valeur finale - Valeur initiale) / Valeur initiale : (460 - 400) / 400 = 60 / 400 = 0,15, soit une progression de +15,0 %.","x":["Correct : (460 - 400) / 400 = 60 / 400 = +15,0 %.","Division erronée par la valeur finale (60 / 460 ≈ 13 %).","Confusion entre l'augmentation en valeur absolue (+60) et le pourcentage.","Erreur d'arrondi sur la valeur finale."]},{"id":"numeric-mean-019","f":"single_best","skill":"moyenne","difficulty":2,"p":"Quelle est la durée moyenne de traitement par dossier sur l'ensemble de la journée ?","s":"Matin : 10 dossiers traités en 20 minutes chacun. Après-midi : 20 dossiers traités en 35 minutes chacun.","o":["30 minutes","27,5 minutes","25 minutes","32,5 minutes"],"a":0,"e":"Calcul de la moyenne pondérée : temps total = (10 × 20) + (20 × 35) = 200 + 700 = 900 minutes. Divisé par 30 dossiers (10 + 20), on obtient 30 minutes par dossier.","x":["Correct : [(10 × 20) + (20 × 35)] / 30 = (200 + 700) / 30 = 900 / 30 = 30 minutes.","Moyenne arithmétique simple non pondérée : (20 + 35) / 2 = 27,5 minutes.","Sous-pondération arbitraire des dossiers de l'après-midi.","Surpondération excessive de l'après-midi."]},{"id":"numeric-ratio-020","f":"single_best","skill":"ratio-proportion","difficulty":2,"p":"Combien d'agents seront affectés au Pôle Accueil selon ce ratio ?","s":"Une enveloppe de 35 nouveaux agents est répartie entre le Pôle Accueil et le Pôle Instruction selon un ratio de 3 pour 4 (3 parts pour l'Accueil, 4 parts pour l'Instruction).","o":["15 agents","20 agents","12 agents","18 agents"],"a":0,"e":"Le ratio 3:4 totalise 7 parts égales. Une part vaut 35 / 7 = 5 agents. Le Pôle Accueil recevant 3 parts, il accueille 3 × 5 = 15 agents.","x":["Correct : total de 3 + 4 = 7 parts ; 1 part = 35 / 7 = 5 agents ; Accueil = 3 × 5 = 15 agents.","Correspond à la part du Pôle Instruction (4 × 5 = 20 agents).","Sous-évaluation résultant d'une erreur de calcul.","Répartition erronée sans respect du dénominateur 7."]},{"id":"numeric-perc-021","f":"single_best","skill":"pourcentage","difficulty":3,"p":"Quel est le prix final du logiciel après l'application de ces deux remises successives ?","s":"Une licence logicielle d'une valeur de 2 000 euros bénéficie d'une remise initiale de 20 %, puis d'une remise additionnelle de 10 % sur le montant résiduel.","o":["1 440 euros","1 400 euros","1 500 euros","1 380 euros"],"a":0,"e":"Après la première remise de 20 %, le prix devient 2 000 € × 0,80 = 1 600 €. La seconde remise de 10 % s'applique sur cette base : 1 600 € × 0,90 = 1 440 euros.","x":["Correct : 2 000 × 0,80 = 1 600 €, puis 1 600 × 0,90 = 1 440 euros.","Additionne à tort les deux taux (20 % + 10 % = 30 % de 2 000 € = 1 400 €).","Sous-estime la remise cumulée.","Erreur de calcul dans la cascade des pourcentages."]},{"id":"numeric-ops-022","f":"single_best","skill":"operations-simples","difficulty":2,"p":"Combien d'heures sont nécessaires pour instruire les 90 dossiers restants avec l'équipe réunie ?","s":"L'agent A instruit 5 dossiers par heure. L'agent B instruit 7 dossiers par heure. L'agent C instruit 3 dossiers par heure. Ils travaillent conjointement.","o":["6 heures","5 heures","7 heures","8 heures"],"a":0,"e":"La cadence conjointe est de 5 + 7 + 3 = 15 dossiers par heure. Pour traiter 90 dossiers, le temps nécessaire est de 90 / 15 = 6 heures.","x":["Correct : cadence cumulée = 5 + 7 + 3 = 15 dossiers/h ; 90 / 15 = 6 heures.","À 15 dossiers/h, 5 heures ne produiraient que 75 dossiers.","Surestimation de la durée requise.","Correspondrait au travail sans l'agent B."]},{"id":"numeric-table-023","f":"single_best","skill":"lecture-tableau","difficulty":2,"p":"Quel est le montant total des crédits restants non consommés au 31 décembre ?","s":{"type":"table","caption":"Consommation budgétaire par programme (en milliers d'euros)","headers":["Programme","Budget alloué","Budget consommé"],"rows":[["Programme 1",500,420],["Programme 2",300,270],["Programme 3",200,160]]},"o":["150 milliers d'euros","130 milliers d'euros","170 milliers d'euros","140 milliers d'euros"],"a":0,"e":"Les reliquats non consommés s'élèvent à : Programme 1 = 80 k€, Programme 2 = 30 k€, Programme 3 = 40 k€. La somme totale est de 80 + 30 + 40 = 150 milliers d'euros.","x":["Correct : écarts respectifs = (500 - 420) + (300 - 270) + (200 - 160) = 80 + 30 + 40 = 150 milliers d'euros.","Sous-estime le reliquat du Programme 1.","Erreur d'addition sur les crédits résiduels.","Omet une partie des reliquats budgétaires."]},{"id":"numeric-var-024","f":"single_best","skill":"variation","difficulty":2,"p":"De combien de points de pourcentage le taux de réussite a-t-il varié ?","s":"Le taux de réussite à l'examen passe de 45 % lors de la session de printemps à 58 % lors de la session d'automne.","o":["+13 points","+28,9 %","+13 %","+10 points"],"a":0,"e":"La différence arithmétique directe entre deux pourcentages s'exprime en points de pourcentage : 58 − 45 = 13 points de pourcentage.","x":["Correct : 58 - 45 = 13 points de pourcentage d'écart absolu.","Progression relative : (58 - 45) / 45 ≈ +28,9 %, et non écart en points.","Confusion d'unité : l'écart entre deux taux s'exprime en points et non en pour cent.","Erreur arithmétique de soustraction."]},{"id":"numeric-mean-025","f":"single_best","skill":"moyenne","difficulty":2,"p":"Quelle est la moyenne arithmétique simple des cinq notes obtenues ?","s":"Notes obtenues aux cinq épreuves du concours : 12/20, 14/20, 15/20, 11/20, 18/20.","o":["14,0 / 20","13,5 / 20","14,5 / 20","15,0 / 20"],"a":0,"e":"La somme des notes est 12 + 14 + 15 + 11 + 18 = 70. Divisée par 5 épreuves, la moyenne simple est de 70 / 5 = 14,0 / 20.","x":["Correct : (12 + 14 + 15 + 11 + 18) / 5 = 70 / 5 = 14,0 / 20.","Sous-estime la somme des notes de 2,5 points.","Surestimation résultant d'une erreur d'addition.","Arrondi excessif sans justification mathématique."]},{"id":"numeric-scale-026","f":"single_best","skill":"ratio-proportion","difficulty":2,"p":"Quelle est la distance réelle sur le terrain correspondant à ce tracé ?","s":"Sur un plan cadastral à l'échelle 1:5 000, une voie d'accès mesure 6 centimètres.","o":["300 mètres","30 mètres","3 000 mètres","600 mètres"],"a":0,"e":"Distance réelle = 6 cm × 5 000 = 30 000 cm. Converti en mètres (1 m = 100 cm), cela équivaut à 30 000 / 100 = 300 mètres.","x":["Correct : 6 cm × 5 000 = 30 000 cm = 300 mètres.","Erreur d'un facteur 10 dans la conversion d'unités (30 m).","Erreur par excès d'un facteur 10 (3 000 m).","Confusion dans la multiplication (6 × 10 000 au lieu de 6 × 5 000)."]},{"id":"numeric-perc-027","f":"single_best","skill":"pourcentage","difficulty":2,"p":"Combien d'agents participent régulièrement au télétravail ?","s":"Sur un effectif total de 450 agents, 40 % bénéficient d'une convention de télétravail régulière.","o":["180 agents","175 agents","190 agents","200 agents"],"a":0,"e":"Le calcul est direct : 450 × (40 / 100) = 45 × 4 = 180 agents.","x":["Correct : 450 × 0,40 = 180 agents.","Calcul erroné basé sur 38,9 %.","Surestimation correspondant à 42,2 %.","Calcul correspondant à 44,4 % de l'effectif."]},{"id":"numeric-var-028","f":"single_best","skill":"variation","difficulty":2,"p":"Quel est le pourcentage de baisse de la consommation de papier ?","s":"La consommation annuelle de rames de papier passe de 5 000 rames à 3 500 rames grâce à la dématérialisation.","o":["-30,0 %","-25,0 %","-1 500 %","-35,0 %"],"a":0,"e":"La variation relative est (3 500 - 5 000) / 5 000 = -1 500 / 5 000 = -0,30, soit une diminution de 30,0 %.","x":["Correct : (3 500 - 5 000) / 5 000 = -1 500 / 5 000 = -30,0 %.","Sous-estime la réduction en divisant par une base erronée.","Confusion entre volume absolu (-1 500 rames) et pourcentage.","Division par la valeur finale au lieu de la valeur initiale (-1 500 / 3 500 ≈ -42,8 %)."]},{"id":"numeric-mean-029","f":"single_best","skill":"moyenne","difficulty":2,"p":"Quelle est la note globale pondérée du candidat ?","s":"Épreuve écrite (coefficient 4) : 15/20. Épreuve orale (coefficient 6) : 12/20.","o":["13,2 / 20","13,5 / 20","13,0 / 20","13,8 / 20"],"a":0,"e":"Moyenne pondérée : points totaux = (15 × 4) + (12 × 6) = 60 + 72 = 132. Divisé par la somme des coefficients (4 + 6 = 10), le résultat est 132 / 10 = 13,2 / 20.","x":["Correct : [(15 × 4) + (12 × 6)] / (4 + 6) = (60 + 72) / 10 = 132 / 10 = 13,2 / 20.","Moyenne arithmétique simple non pondérée : (15 + 12) / 2 = 13,5 / 20.","Sous-évaluation sans respect des coefficients.","Inversion des coefficients en faveur de l'écrit [(15 × 6) + (12 × 4)] / 10 = 13,8."]},{"id":"numeric-ratio-030","f":"single_best","skill":"ratio-proportion","difficulty":2,"p":"Quel volume d'archivage reste-t-il à traiter au service Numérisation ?","s":"Sur un fonds total de 1 200 cartons, le rapport entre cartons traités et cartons non traités est de 3 pour 1.","o":["300 cartons","400 cartons","900 cartons","250 cartons"],"a":0,"e":"Le ratio 3:1 correspond à 4 parts au total. Chaque part représente 1 200 / 4 = 300 cartons. La part restante non traitée étant de 1, il reste 300 cartons.","x":["Correct : 3 + 1 = 4 parts ; 1 part (non traités) = 1 200 / 4 = 300 cartons.","Calcul erroné divisant par 3 au lieu de 4.","Correspond aux cartons déjà traités (3 parts = 900 cartons).","Sous-évaluation du reliquat d'archivage."]},{"id":"numeric-ops-031","f":"single_best","skill":"operations-simples","difficulty":1,"p":"Quel est le coût moyen de repas par agent lors de ce séminaire ?","s":"La facture de restauration s'élève à 1 800 euros pour un groupe de 75 participants.","o":["24 euros","22 euros","25 euros","26 euros"],"a":0,"e":"Division simple : 1 800 € / 75 = 24 euros par participant.","x":["Correct : 1 800 / 75 = 24 euros par participant.","Sous-estime le coût unitaire réel.","Arrondi arbitraire à 25 euros.","Surestimation arithmétique."]},{"id":"numeric-perc-032","f":"single_best","skill":"pourcentage","difficulty":2,"p":"Combien d'agents ont formulé une demande de mobilité interne ?","s":"Au sein d'un ministère comptant 800 agents, 15 % ont déposé une demande de mobilité cette année.","o":["120 agents","110 agents","130 agents","125 agents"],"a":0,"e":"Calcul direct : 800 × (15 / 100) = 8 × 15 = 120 agents.","x":["Correct : 800 × 0,15 = 120 agents.","Correspondrait à un taux de 13,75 %.","Correspondrait à un taux de 16,25 %.","Erreur d'arrondi sur le calcul direct."]},{"id":"numeric-table-033","f":"single_best","skill":"lecture-tableau","difficulty":2,"p":"Quel trimestre affiche la plus forte progression absolue de dossiers clôturés par rapport au trimestre précédent ?","s":{"type":"table","caption":"Dossiers clôturés par trimestre","headers":["Trimestre","Dossiers clôturés"],"rows":[["T1",300],["T2",380],["T3",440],["T4",490]]},"o":["Trimestre 2","Trimestre 3","Trimestre 4","Trimestre 2 et Trimestre 3 à égalité"],"a":0,"e":"Écarts absolus successifs : T2 - T1 = 380 - 300 = +80 ; T3 - T2 = 440 - 380 = +60 ; T4 - T3 = 490 - 440 = +50. La plus forte hausse en valeur absolue a lieu au Trimestre 2 (+80 dossiers).","x":["Correct : T2 gagne +80 dossiers (380 - 300), contre +60 en T3 et +50 en T4.","T3 gagne 440 - 380 = 60 dossiers, soit moins que T2.","T4 gagne 490 - 440 = 50 dossiers, soit moins que T2.","Les progressions trimestrielles sont distinctes (80 vs 60 dossiers)."]},{"id":"numeric-var-034","f":"single_best","skill":"variation","difficulty":3,"p":"Quel est le budget final après ces deux variations annuelles consécutives ?","s":"Un budget de fonctionnement de 100 000 euros diminue de 20 % en année 1, puis augmente de 20 % en année 2 sur la base du montant réduit.","o":["96 000 euros","100 000 euros","98 000 euros","94 000 euros"],"a":0,"e":"Année 1 : 100 000 € × 0,80 = 80 000 €. Année 2 : 80 000 € × 1,20 = 96 000 €. Le montant final accuse une baisse nette de 4 % par rapport au budget initial.","x":["Correct : 100 000 × 0,80 = 80 000 €, puis 80 000 × 1,20 = 96 000 euros.","Erreur classique consistant à croire qu'une hausse de 20 % compense une baisse de 20 %.","Calcul erroné minorant la perte globale.","Sous-estimation excessive du budget reconstitué."]},{"id":"numeric-mean-035","f":"single_best","skill":"moyenne","difficulty":2,"p":"Combien d'appels le centre de contact traite-t-il en moyenne par heure ?","s":"Le centre d'appel a réceptionné 540 communications téléphoniques au cours d'une journée continue de 9 heures d'ouverture.","o":["60 appels","55 appels","65 appels","50 appels"],"a":0,"e":"La moyenne horaire s'obtient en divisant le total des appels par le nombre d'heures d'ouverture : 540 / 9 = 60 appels par heure.","x":["Correct : 540 / 9 = 60 appels par heure.","Sous-estime le flux horaire moyen (55 × 9 = 495).","Surestimation du flux horaire (65 × 9 = 585).","Sous-évaluation excessive (50 × 9 = 450)."]}],"planning":[{"id":"planning-slot-001","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quel créneau permet d'organiser une réunion de 45 minutes commune aux deux participants ?","s":"Léa est disponible de 9 h 00 à 10 h 30 et de 14 h 00 à 15 h 00. Sam est disponible de 9 h 30 à 11 h 00 et de 14 h 30 à 16 h 00.","o":["9 h 00 à 9 h 45","9 h 30 à 10 h 15","14 h 00 à 14 h 45","14 h 30 à 15 h 15"],"a":1,"e":"Le créneau commun le matin s'étend de 9 h 30 à 10 h 30 (durée 60 min). La réunion de 45 minutes peut donc se tenir de 9 h 30 à 10 h 15. Les autres créneaux empiètent sur l'indisponibilité de l'un des participants (Sam avant 9 h 30 le matin ou avant 14 h 30 l'après-midi ; Léa après 15 h 00).","x":["Sam n'est pas disponible avant 9 h 30.","Correct : les deux participants sont disponibles simultanément de 9 h 30 à 10 h 30.","Sam n'est pas disponible avant 14 h 30.","Léa n'est plus disponible après 15 h 00 (la réunion se terminerait à 15 h 15)."]},{"id":"planning-prio-002","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quelle tâche devez-vous impérativement démarrer en premier ?","s":"Il est 9 h 00. Tâche A : échéance 10 h 00, durée 20 min. Tâche B : échéance demain, durée 15 min. Tâche C : échéance aujourd'hui 16 h 00, durée 60 min. Tâche D : échéance 11 h 30, durée 90 min.","o":["Tâche A","Tâche B","Tâche C","Tâche D"],"a":0,"e":"Commencer par A (9 h 00 – 9 h 20) respecte son échéance de 10 h 00 et laisse D se terminer à 10 h 50, avant 11 h 30. Commencer par D ferait manquer l'échéance de A. B et C ont des échéances plus lointaines.","x":["Correct : son échéance (10 h 00) est la plus imminente et impose un démarrage sans attendre.","Échéance fixée au lendemain, donc bien moins urgente que la tâche A.","Échéance fixée à 16 h 00, laissant une marge temporelle suffisante après réalisation de A.","Commencer par D (90 min) mènerait à 10 h 30 : A finirait à 10 h 50, après son échéance de 10 h 00."]},{"id":"planning-order-003","f":"single_best","skill":"dependances","difficulty":1,"p":"Quel ordonnancement respecte l'intégralité des contraintes de préséance imposées ?","s":"L'étape X doit impérativement précéder l'étape Y. L'étape Z doit être réalisée après l'étape Y.","o":["Z, puis X, puis Y","X, puis Z, puis Y","Y, puis X, puis Z","X, puis Y, puis Z"],"a":3,"e":"Les contraintes X < Y et Y < Z imposent strictement l'enchaînement direct X, puis Y, puis Z.","x":["Viole les deux contraintes : Z est placé avant Y, et Y est placé après Z.","Viole la contrainte imposant que Z soit réalisé après Y.","Viole la préséance stricte de X sur Y.","Correct : respecte successivement X avant Y, puis Y avant Z."]},{"id":"planning-room-004","f":"single_best","skill":"conflits","difficulty":2,"p":"Quel créneau faut-il réserver pour satisfaire l'ensemble des contraintes ?","s":"Entretien de 30 minutes avant midi. Salle libre de 10:00 à 10:30 et de 11:00 à 12:00. Candidate indisponible de 10:15 à 11:15.","o":["10:00 à 10:30","10:15 à 10:45","11:00 à 11:30","11:15 à 11:45"],"a":3,"e":"La candidate se libère à 11:15 et la salle est libre jusqu'à 12:00 ; le créneau 11:15-11:45 offre 30 minutes effectives sans conflit.","x":["Conflit avec la candidate dès 10:15, ne laissant que 15 minutes utiles.","La candidate est en indisponibilité sur l'ensemble de cette plage horaire.","La candidate n'est pas encore disponible entre 11:00 et 11:15.","Correct : la salle est libre jusqu'à midi et la candidate est disponible dès 11:15 pour 30 minutes."]},{"id":"planning-delay-005","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quel ordre de traitement minimise le risque de dépassement de délai ?","s":"À 13 h 00 : dossier urgent (durée 45 min, échéance 14 h 00), appel de cadrage (durée 15 min, avant 15 h 00), note de synthèse (durée 90 min, pour le lendemain).","o":["Note de synthèse, appel, dossier urgent","Dossier urgent, appel, note de synthèse","Appel, note de synthèse, dossier urgent","Note de synthèse, dossier urgent, appel"],"a":1,"e":"Le dossier urgent doit se terminer à 13:45 pour respecter l'échéance de 14:00, suivi de l'appel (13:45-14:00), laissant le temps pour la note.","x":["La note de 90 min repousse l'urgence à 14:30, provoquant un dépassement de délai.","Correct : dossier urgent terminé à 13:45 (avant 14:00), appel à 14:00, puis note de synthèse.","Placer la note à 13:15 repousse le dossier urgent à 14:45, après son échéance.","Prioriser la note de 90 min fait manquer l'échéance de 14:00 du dossier urgent."]},{"id":"planning-crit-006","f":"single_best","skill":"dependances","difficulty":3,"p":"Quelle est la durée minimale incompressible pour finaliser ce projet ?","s":"Phase 1 (durée 3 jours). Puis en parallèle : Phase 2A (durée 4 jours) et Phase 2B (durée 6 jours). Enfin Phase 3 (durée 2 jours), démarrant dès que 2A et 2B sont terminées.","o":["11 jours","9 jours","15 jours","13 jours"],"a":0,"e":"Entre 2A et 2B menées en parallèle, le chemin le plus long impose 6 jours. La durée totale incompressible est donc 3 + max(4, 6) + 2 = 3 + 6 + 2 = 11 jours.","x":["Correct : chemin critique déterminé par 3 + max(4, 6) + 2 = 3 + 6 + 2 = 11 jours.","Calcule à tort sur la branche parallèle la plus rapide 2A (3 + 4 + 2 = 9).","Additionne toutes les phases en série sans exploiter la parallélisation (3 + 4 + 6 + 2 = 15).","Surévaluation arbitraire de deux jours par rapport au chemin critique réel."]},{"id":"planning-capa-007","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"Combien d'agents supplémentaires faut-il mobiliser pour respecter l'échéance ?","s":"Un chantier d'archivage requiert 120 heures-agent à livrer en 5 jours de 8 heures de travail. L'équipe actuelle compte 2 agents.","o":["1 agent supplémentaire","2 agents supplémentaires","3 agents supplémentaires","4 agents supplémentaires"],"a":0,"e":"En 5 jours, 1 agent produit 5 × 8 = 40 heures. Pour réaliser 120 heures, il faut 120 / 40 = 3 agents au total. Deux étant déjà présents, il faut 1 agent de plus.","x":["Correct : besoin total de 3 agents (120 h / 40 h), 2 étant déjà affectés, 1 agent suffit en renfort.","Confond le nombre d'agents déjà en poste avec le besoin de renfort additionnel.","Indique l'effectif global nécessaire sans soustraire les 2 agents déjà en place.","Surdimensionne l'équipe à 6 agents au total, soit le double de la charge requise."]},{"id":"planning-overlap-008","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quelle est l'heure d'arrivée la plus tardive possible pour l'agent C, qui reste ensuite jusqu'à 18 h ?","s":"La permanence au guichet doit être assurée sans interruption de 8 h à 18 h. Agent A : 8 h à 12 h. Agent B : 11 h 30 à 15 h 30. L'agent C assure la fin de journée.","o":["15 h 30","16 h 00","12 h 00","17 h 00"],"a":0,"e":"Le guichet est couvert par A puis B jusqu'à 15 h 30. L'agent C doit être présent au plus tard à ce moment ; 12 h fonctionne aussi, mais ce n'est pas l'heure la plus tardive possible.","x":["Correct : l'agent B quittant son poste à 15 h 30, c'est l'heure limite exacte pour éviter une rupture de permanence.","Une arrivée à 16 h 00 entraînerait 30 minutes de fermeture non autorisée du guichet.","Une arrivée à 12 h 00 assure la continuité mais ne constitue pas l'horaire le plus tardif possible.","Une arrivée à 17 h 00 créerait une interruption de service prolongée de 1 h 30."]},{"id":"planning-buffer-009","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"De combien de jours ouvrés le projet peut-il au plus être retardé sans dépasser l'échéance ?","s":"L'échéance de livraison tombe dans 20 jours ouvrés. Les tâches restantes du chemin critique totalisent 16 jours ouvrés.","o":["4 jours ouvrés","2 jours ouvrés","6 jours ouvrés","8 jours ouvrés"],"a":0,"e":"Les deux durées sont exprimées dans la même unité (jours ouvrés). La marge totale vaut 20 − 16 = 4 jours ouvrés.","x":["Correct : la marge de battement s'élève exactement à 20 - 16 = 4 jours ouvrés.","Sous-estime de 2 jours la marge réelle disponible.","Surestime la marge de 2 jours, ce qui risquerait d'entraîner un retard effectif.","Surestimation excessive qui provoquerait un dépassement d'échéance certain de 4 jours."]},{"id":"planning-dep-010","f":"single_best","skill":"dependances","difficulty":2,"p":"Sur quelle action pouvez-vous avancer dès ce matin ?","s":"Validation hiérarchique : en attente du rapport financier. Rapport financier : en cours de relecture finale. Envoi des convocations : après la validation. Diffusion du compte rendu : après l'envoi des convocations.","o":["Terminer la relecture du rapport","Obtenir la validation hiérarchique","Envoyer les convocations","Diffuser le compte rendu"],"a":0,"e":"Chaque étape dépend de la précédente : validation, puis convocations, puis compte rendu, et tout attend le rapport financier. Seule sa relecture finale peut avancer dès ce matin.","x":["Correct : c'est la seule tâche immédiatement actionnable dont toutes les dépendances sont levées.","Bloquée tant que le rapport financier n'a pas été finalisé.","Bloquée par la dépendance envers la validation hiérarchique.","Bloquée par les étapes préalables de convocation et de déroulement de la réunion."]},{"id":"planning-trio-011","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quel créneau horaire permet de tenir un point de synchronisation de 30 minutes commun aux trois agents ?","s":"Agent 1 est disponible de 14 h 00 à 16 h 00. Agent 2 est disponible de 14 h 30 à 17 h 00. Agent 3 est disponible de 13 h 30 à 15 h 30.","o":["14 h 30 à 15 h 00","14 h 00 à 14 h 30","15 h 30 à 16 h 00","16 h 00 à 16 h 30"],"a":0,"e":"La plage commune aux trois agents correspond à l'intersection des créneaux : à partir de 14 h 30 (arrivée de l'Agent 2) et jusqu'à 15 h 30 (départ de l'Agent 3). Le créneau de 14 h 30 à 15 h 00 s'y inscrit parfaitement.","x":["Correct : les trois agents sont simultanément disponibles sur la plage 14 h 30 à 15 h 30.","L'Agent 2 n'est pas encore disponible avant 14 h 30.","L'Agent 3 a terminé sa disponibilité à 15 h 30.","Les Agents 1 et 3 ne sont plus disponibles après 16 h 00."]},{"id":"planning-prio-012","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quelle tâche devez-vous impérativement démarrer dès 14 h 00 pour ne manquer aucune échéance ?","s":"Il est 14 h 00. Tâche 1 : durée 40 min, échéance 15 h 00. Tâche 2 : durée 50 min, échéance 15 h 30. Tâche 3 : durée 30 min, échéance 17 h 00.","o":["Tâche 1","Tâche 2","Tâche 3","Tâche 2 suivie de Tâche 3"],"a":0,"e":"En démarrant par Tâche 1, celle-ci s'achève à 14 h 40 (avant 15 h 00). Tâche 2 peut ensuite s'exécuter de 14 h 40 à 15 h 30, respectant pile son échéance. Si l'on commençait par Tâche 2, Tâche 1 ne finirait qu'à 15 h 30, soit 30 minutes après son échéance.","x":["Correct : commencer par Tâche 1 (14 h 00 à 14 h 40) permet ensuite d'achever Tâche 2 à 15 h 30 avant son terme.","Commencer par Tâche 2 (14 h 00 à 14 h 50) repousserait Tâche 1 à 15 h 30, dépassant son échéance de 15 h 00.","La Tâche 3 a une échéance tardive (17 h 00) et n'est pas prioritaire.","Inverser l'ordre en commençant par Tâche 2 provoque un retard certain sur Tâche 1."]},{"id":"planning-room-013","f":"single_best","skill":"conflits","difficulty":2,"p":"Quel créneau permet de planifier une séance de formation de 45 minutes dans la salle Polyvalente ?","s":"La salle Polyvalente est occupée de 9 h 00 à 10 h 30 et de 11 h 15 à 12 h 30. Le formateur est présent de 10 h 00 à 12 h 00.","o":["10 h 30 à 11 h 15","10 h 00 à 10 h 45","11 h 15 à 12 h 00","11 h 30 à 12 h 15"],"a":0,"e":"La seule fenêtre de disponibilité conjointe de la salle (libre entre 10 h 30 et 11 h 15) et du formateur (présent de 10 h 00 à 12 h 00) est exactement la plage 10 h 30 à 11 h 15, d'une durée de 45 minutes.","x":["Correct : la salle est libre de 10 h 30 à 11 h 15 (45 min) et le formateur y est disponible.","La salle est occupée jusqu'à 10 h 30.","La salle est réservée par une autre réunion à partir de 11 h 15.","Conflit direct d'occupation de la salle qui est prise dès 11 h 15."]},{"id":"planning-chain-014","f":"single_best","skill":"dependances","difficulty":3,"p":"Quelle est la date d'achèvement au plus tôt de l'ensemble des travaux ?","s":"Le projet débute le lundi matin (jour 1). Étape A (3 jours ouvrés). Puis en parallèle, Étape B (2 jours ouvrés) et Étape C (4 jours ouvrés). Étape D (1 jour ouvré) ne démarre que lorsque B et C sont toutes deux achevées. L'équipe ne travaille que les jours ouvrés (du lundi au vendredi).","o":["Jour ouvré 8 (mercredi de la 2e semaine)","Jour ouvré 10 (vendredi de la 2e semaine)","Jour ouvré 6 (lundi de la 2e semaine)","Jour ouvré 7 (mardi de la 2e semaine)"],"a":0,"e":"L'étape A prend les jours 1, 2 et 3. Les étapes B et C se déroulent en parallèle du jour 4 au jour 7 (l'étape critique C imposant 4 jours). L'étape D intervient ensuite sur le jour 8. Le projet s'achève donc au jour ouvré 8.","x":["Correct : chemin critique = Étape A (3 j) + max(Étape B: 2 j, Étape C: 4 j) + Étape D (1 j) = 3 + 4 + 1 = 8 jours ouvrés.","Résultat obtenu en sommant toutes les étapes sans tenir compte du parallélisme de B et C (3 + 2 + 4 + 1 = 10).","Calcul erroné ignorant la durée de l'étape la plus longue en parallèle.","Omet la durée de l'étape finale D."]},{"id":"planning-buffer-015","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"À quelle heure au plus tard l'instruction du dossier doit-elle débuter pour respecter l'échéance ?","s":"Un dossier d'agrément requiert 2 h 30 de travail continu. Il doit impérativement être transmis par courriel avant 17 h 00. Une coupure réseau obligatoire et planifiée de 30 minutes a lieu de 15 h 00 à 15 h 30, interdisant toute instruction.","o":["14 h 00","14 h 30","13 h 30","15 h 00"],"a":0,"e":"Le travail effectif demande 2 h 30. Comme la plage d'instruction chevauche nécessairement la coupure réseau de 15 h 00 à 15 h 30 (30 min), le temps global nécessaire est de 2 h 30 + 30 min = 3 h 00. Pour finir à 17 h 00, le travail doit débuter au plus tard à 14 h 00 (14 h 00 – 15 h 00 : 1 h ; 15 h 30 – 17 h 00 : 1 h 30).","x":["Correct : 2 h 30 de travail + 30 min d'interruption = 3 h de temps total requis. 17 h 00 - 3 h = 14 h 00.","Ne prend pas en compte la coupure réseau de 30 minutes, ce qui ferait finir à 17 h 30.","Avance inutilement le démarrage de 30 minutes par rapport à l'heure limite.","Démarrage impossible : la coupure réseau débute précisément à 15 h 00."]},{"id":"planning-meet-016","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quel créneau de 45 minutes permet de réunir les deux chefs de service ce matin ?","s":"Chef de service A : libre de 8 h 30 à 10 h 00 et de 11 h 00 à 12 h 30. Chef de service B : libre de 9 h 15 à 11 h 30.","o":["9 h 15 à 10 h 00","8 h 30 à 9 h 15","10 h 00 à 10 h 45","11 h 30 à 12 h 15"],"a":0,"e":"La première plage commune se situe entre 9 h 15 et 10 h 00 (durée 45 minutes). La seconde plage commune s'étend de 11 h 00 à 11 h 30 (30 minutes seulement, insuffisant). Le seul créneau possible de 45 minutes est 9 h 15 à 10 h 00.","x":["Correct : intersection matinale commune de 9 h 15 à 10 h 00 (45 minutes effectives).","Le chef de service B n'est pas disponible avant 9 h 15.","Le chef de service A est indisponible de 10 h 00 à 11 h 00.","Le chef de service B n'est plus disponible après 11 h 30."]},{"id":"planning-prio-017","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quelle tâche devez-vous impérativement planifier en premier ce matin ?","s":"Il est 8 h 30. Tâche 1 : transmission bordereau (durée 30 min, échéance 9 h 30). Tâche 2 : préparation séance (durée 60 min, échéance 11 h 30). Tâche 3 : synthèse mensuelle (durée 45 min, échéance 16 h 00).","o":["Tâche 1","Tâche 2","Tâche 3","Tâche 2 ou Tâche 3 indifféremment"],"a":0,"e":"La Tâche 1 a l'échéance la plus rapprochée (9 h 30). La commencer dès 8 h 30 permet de la clore à 9 h 00, laissant tout le temps nécessaire pour enchaîner la Tâche 2 (9 h 00 – 10 h 00) bien avant son échéance de 11 h 30.","x":["Correct : échéance à 9 h 30, ne laissant qu'une heure de marge pour 30 minutes de travail.","Son échéance à 11 h 30 permet une exécution sereine après achèvement de la Tâche 1.","Échéance fixée à 16 h 00, non prioritaire ce matin.","L'imminence de la Tâche 1 interdit toute substitution."]},{"id":"planning-room-018","f":"single_best","skill":"conflits","difficulty":2,"p":"Quelle salle faut-il réserver pour tenir une séance de 60 minutes entre 14 h 00 et 16 h 00 ?","s":"Salle Athéna : occupée de 14 h 00 à 15 h 15. Salle Mercure : libre de 14 h 30 à 15 h 45. Salle Minerve : occupée de 14 h 45 à 16 h 00.","o":["Salle Mercure","Salle Athéna","Salle Minerve","Aucune des trois salles"],"a":0,"e":"La séance requiert 60 minutes consécutives. La salle Mercure est disponible pendant 1 h 15 (de 14 h 30 à 15 h 45), ce qui permet d'y caler la réunion d'une heure (ex. de 14 h 30 à 15 h 30). Les autres salles n'offrent que 45 minutes libres.","x":["Correct : Mercure est libre de 14 h 30 à 15 h 45 (plage disponible de 75 minutes, suffisant pour 60 minutes).","Athéna ne laisse que 45 minutes utiles (15 h 15 à 16 h 00).","Minerve ne laisse que 45 minutes utiles (14 h 00 à 14 h 45).","La salle Mercure offre un créneau continu suffisant."]},{"id":"planning-dep-019","f":"single_best","skill":"dependances","difficulty":2,"p":"Quelle séquence d'étapes respecte strictement l'ensemble des contraintes de dépendance ?","s":"L'étape 1 doit précéder l'étape 2. L'étape 3 ne peut démarrer qu'après la fin conjointe des étapes 1 et 2. L'étape 4 conclut le processus après l'étape 3.","o":["Étape 1, puis Étape 2, puis Étape 3, puis Étape 4","Étape 2, puis Étape 1, puis Étape 3, puis Étape 4","Étape 3, puis Étape 1, puis Étape 2, puis Étape 4","Étape 1, puis Étape 3, puis Étape 2, puis Étape 4"],"a":0,"e":"Les contraintes (1 avant 2), (2 avant 3) et (3 avant 4) imposent un ordre séquentiel unique : Étape 1 → Étape 2 → Étape 3 → Étape 4.","x":["Correct : respecte successivement 1 avant 2, 2 avant 3, puis 4 en clôture.","Viole la dépendance initiale imposant que l'étape 1 précède l'étape 2.","Viole la condition imposant que l'étape 3 démarre après les étapes 1 et 2.","Place l'étape 3 avant l'étape 2 alors que l'étape 2 conditionne l'étape 3."]},{"id":"planning-buffer-020","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"De combien de minutes de marge de sécurité disposez-vous avant l'échéance de 17 h 00 ?","s":"Il est 14 h 00. Vous devez réaliser trois tâches successives : Révision de dossier (durée 60 min), Appel de cadrage (durée 30 min), et Rédaction d'avis (durée 60 min). L'échéance finale est fixée à 17 h 00.","o":["30 minutes","15 minutes","45 minutes","0 minute"],"a":0,"e":"Le cumul des durées de travail est de 60 + 30 + 60 = 150 minutes, soit 2 heures et 30 minutes. Démarrées à 14 h 00, les tâches s'achèvent à 16 h 30. La marge de sécurité avant 17 h 00 est donc de 30 minutes.","x":["Correct : temps de travail = 60 + 30 + 60 = 150 min (2 h 30) ; 14 h 00 + 2 h 30 = 16 h 30 ; marge = 30 minutes jusqu'à 17 h 00.","Sous-estime la marge de sécurité disponible.","Surestimation minorant la durée des tâches.","Considère à tort que l'ensemble de la plage horaire est consommé."]},{"id":"planning-meet-021","f":"single_best","skill":"disponibilites","difficulty":3,"p":"Quel créneau permet de tenir un point de 30 minutes réunissant les trois collaborateurs ?","s":"Collaborateur X : disponible de 10 h 00 à 12 h 00. Collaborateur Y : disponible de 9 h 30 à 11 h 15. Collaborateur Z : disponible de 10 h 45 à 12 h 30.","o":["10 h 45 à 11 h 15","10 h 00 à 10 h 30","11 h 15 à 11 h 45","10 h 30 à 11 h 00"],"a":0,"e":"Collaborateur X est libre de 10 h 00 à 12 h 00, Y de 9 h 30 à 11 h 15, et Z de 10 h 45 à 12 h 30. L'unique créneau où tous les trois sont simultanément disponibles est 10 h 45 – 11 h 15 (exactement 30 minutes).","x":["Correct : intersection des trois disponibilités : X (jusqu'à 12h), Y (jusqu'à 11h15), Z (dès 10h45). Plage commune = 10 h 45 à 11 h 15.","Z n'est pas encore disponible avant 10 h 45.","Y n'est plus disponible après 11 h 15.","Z n'est pas encore disponible entre 10 h 30 et 10 h 45."]},{"id":"planning-prio-022","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quel ordonnancement permet de respecter toutes les échéances ?","s":"À 9 h 00 : Tâche Alpha (durée 45 min, échéance 10 h 00). Tâche Bêta (durée 30 min, échéance 11 h 00). Tâche Gamma (durée 60 min, échéance 12 h 30).","o":["Alpha (9h00-9h45), puis Bêta (9h45-10h15), puis Gamma (10h15-11h15)","Bêta (9h00-9h30), puis Alpha (9h30-10h15), puis Gamma (10h15-11h15)","Gamma (9h00-10h00), puis Alpha (10h00-10h45), puis Bêta (10h45-11h15)","Alpha (9h00-9h45), puis Gamma (9h45-10h45), puis Bêta (10h45-11h15)"],"a":0,"e":"Seule la séquence Alpha → Bêta → Gamma respecte les échéances de chacun : Alpha est livrée à 9 h 45 (avant 10 h 00), Bêta à 10 h 15 (avant 11 h 00) et Gamma à 11 h 15 (bien avant 12 h 30).","x":["Correct : Alpha s'achève à 9 h 45 (< 10h), Bêta à 10 h 15 (< 11h), Gamma à 11 h 15 (< 12h30).","Commencer par Bêta fait finir Alpha à 10 h 15, dépassant son échéance de 10 h 00.","Commencer par Gamma fait manquer l'échéance d'Alpha et compromet Bêta.","Placer Gamma avant Bêta repousse la fin de Bêta à 11 h 15, dépassant son échéance de 11 h 00."]},{"id":"planning-conflit-023","f":"single_best","skill":"conflits","difficulty":2,"p":"Quelle modification minimale résout le conflit d'agenda ?","s":"Deux entretiens individuels de 45 minutes sont calés en Salle 1 : Entretien A de 10 h 00 à 10 h 45 et Entretien B de 10 h 30 à 11 h 15. La Salle 2 est entièrement libre de 10 h 00 à 12 h 00.","o":["Déplacer l'Entretien B en Salle 2 sur son créneau initial de 10 h 30 à 11 h 15.","Raccourcir l'Entretien A à 30 minutes sans changer de salle.","Reporter les deux entretiens au lendemain matin.","Fusionner les deux entretiens en une seule séance collective."],"a":0,"e":"Le conflit réside dans le chevauchement de 15 minutes en Salle 1 (de 10 h 30 à 10 h 45). Comme la Salle 2 est libre sur toute la matinée, déplacer l'Entretien B en Salle 2 résout le conflit sans modifier les horaires des candidats.","x":["Correct : résout immédiatement le chevauchement sans impacter les horaires des participants.","Dégrade la durée requise de l'entretien alors qu'une salle alternative est vacante.","Mesure disproportionnée qui reporte inutilement deux activités programmées.","Non conforme à la nature individuelle et réservée des entretiens."]},{"id":"planning-crit-024","f":"single_best","skill":"dependances","difficulty":3,"p":"Quelle est la durée totale incompressible pour finaliser la procédure ?","s":"Tâche Initiale : 2 jours. Ensuite, deux démarches parallèles : Démarche A (durée 5 jours) et Démarche B (durée 3 jours). Enfin, Tâche de Clôture (durée 1 jour), qui ne démarre qu'une fois A et B achevées.","o":["8 jours","6 jours","11 jours","10 jours"],"a":0,"e":"Les démarches A et B étant menées en parallèle, le délai de la phase intermédiaire est déterminé par la démarche la plus longue (A, soit 5 jours). La durée totale incompressible est donc 2 + 5 + 1 = 8 jours.","x":["Correct : chemin critique = 2 + max(5, 3) + 1 = 2 + 5 + 1 = 8 jours.","Calcule à tort sur la branche la plus courte B (2 + 3 + 1 = 6 jours).","Somme linéaire erronée sans parallélisation (2 + 5 + 3 + 1 = 11 jours).","Surévaluation arbitraire de deux jours."]},{"id":"planning-agenda-025","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"À quelle heure au plus tard l'agent doit-il partir pour respecter le début de sa réunion ?","s":"Une réunion officielle débute à 14 h 30 au Kirchberg. Le trajet en tramway dure 35 minutes. Une marge obligatoire de sécurité de 10 minutes est exigée avant le début de séance.","o":["13 h 45","13 h 55","13 h 30","14 h 00"],"a":0,"e":"Avec la marge de sécurité de 10 minutes, l'agent doit être sur place à 14 h 20. En retranchant les 35 minutes de transport, l'heure limite de départ est 14 h 20 − 35 min = 13 h 45.","x":["Correct : arrivée requise à 14 h 20 (14h30 - 10 min) ; départ à 14 h 20 - 35 min = 13 h 45.","Omet les 10 minutes de marge de sécurité (départ à 14h30 - 35 min = 13 h 55).","Départ prématuré de 15 minutes par rapport au besoin réel.","Arriverait en retard à 14 h 35."]},{"id":"planning-meet-026","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quel créneau horaire permet d'organiser un entretien de 30 minutes l'après-midi ?","s":"Candidat : disponible de 13 h 30 à 15 h 00. Recruteur : disponible de 14 h 15 à 16 h 30.","o":["14 h 15 à 14 h 45","13 h 30 à 14 h 00","14 h 45 à 15 h 15","15 h 00 à 15 h 30"],"a":0,"e":"La période de disponibilité commune s'étend de 14 h 15 (arrivée du recruteur) à 15 h 00 (départ du candidat). L'entretien de 30 minutes peut donc se tenir de 14 h 15 à 14 h 45.","x":["Correct : plage commune de 14 h 15 à 15 h 00 (45 minutes utiles, suffisant pour 30 min).","Le recruteur n'est pas encore disponible avant 14 h 15.","Le candidat n'est plus disponible après 15 h 00 (la séance déborderait de 15 minutes).","Le candidat est absent à partir de 15 h 00."]},{"id":"planning-prio-027","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quelle action est prioritaire selon la matrice urgence/importance administrative ?","s":"Action A : Répondre à une demande parlementaire à échéance ce soir (urgent et important). Action B : Archiver des courriels administratifs anciens (non urgent, non important). Action C : Préparer la commande de papeterie semestrielle (important, non urgent). Action D : Répondre à un appel d'un démarcheur (urgent, non important).","o":["Action A","Action C","Action D","Action B"],"a":0,"e":"Selon les principes d'efficacité administrative et la matrice d'Eisenhower, les tâches à la fois urgentes et hautement importantes (comme une question parlementaire sous astreinte légale) doivent être traitées immédiatement en priorité absolue.","x":["Correct : tâche à la fois urgente et institutionnellement importante avec échéance impérative le jour même.","Importante mais non urgente, planifiable ultérieurement.","Urgence apparente sans portée institutionnelle, à déléguer ou écourter.","Tâche de fond à traiter en temps masqué."]},{"id":"planning-conflit-028","f":"single_best","skill":"conflits","difficulty":2,"p":"Quel créneau permet d'intercaler une réunion de conciliation de 45 minutes sans collision ?","s":"La matinée de l'arbitre est occupée de 8 h 30 à 9 h 45 (Audience 1) et de 10 h 45 à 12 h 00 (Audience 2).","o":["9 h 45 à 10 h 30","9 h 30 à 10 h 15","10 h 15 à 11 h 00","10 h 30 à 11 h 15"],"a":0,"e":"L'arbitre dispose d'un temps libre exact de 9 h 45 à 10 h 45 (durée 1 heure). Une réunion de 45 minutes s'y insère parfaitement, par exemple de 9 h 45 à 10 h 30, sans empiéter sur aucune audience.","x":["Correct : intervalle libre de 9 h 45 à 10 h 45 (60 minutes disponibles, suffisant pour 45 minutes).","Conflit avec l'Audience 1 qui ne s'achève qu'à 9 h 45.","Conflit avec l'Audience 2 qui démarre à 10 h 45.","Conflit direct avec l'Audience 2 dès 10 h 45."]},{"id":"planning-dep-029","f":"single_best","skill":"dependances","difficulty":2,"p":"Quelle tâche peut débuter dès le matin sans attendre les autres livrables ?","s":"Tâche 1 (Rapport financier) : en attente des chiffres comptables. Tâche 2 (Revue de presse) : aucune dépendance préalable requise. Tâche 3 (Validation budgétaire) : dépend de la fin du Rapport financier. Tâche 4 (Diffusion du PV) : dépend de la Validation budgétaire.","o":["Tâche 2","Tâche 1","Tâche 3","Tâche 4"],"a":0,"e":"Toutes les tâches font partie d'une chaîne séquentielle dépendante du rapport financier, à l'exception de la Tâche 2 (Revue de presse), qui est autonome et peut être traitée immédiatement dès le matin.","x":["Correct : c'est la seule tâche autonome dont l'exécution n'est soumise à aucun prérequis bloquant.","Bloquée par l'attente des chiffres comptables.","Bloquée en cascade par la Tâche 1.","Bloquée en cascade par la Tâche 3."]},{"id":"planning-agenda-030","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"Combien d'agents supplémentaires faut-il mobiliser pour achever la saisie dans le délai imparti ?","s":"Volume total de travail : 160 heures-agent. Le délai de livraison est fixé à 5 jours ouvrés, à raison de 8 heures de travail par agent et par jour. L'équipe actuelle comprend 2 agents.","o":["2 agents supplémentaires","1 agent supplémentaire","3 agents supplémentaires","4 agents supplémentaires"],"a":0,"e":"En 5 jours de 8 heures, un agent effectue 40 heures. Pour accomplir 160 heures, il faut 160 / 40 = 4 agents. Deux agents étant déjà en place, il convient d'en ajouter 4 − 2 = 2 supplémentaires.","x":["Correct : 1 agent produit 5 × 8 = 40 h ; besoin total = 160 / 40 = 4 agents ; 4 - 2 = 2 agents en renfort.","1 agent de renfort ne fournirait que 120 heures au total (3 × 40 h), laissant 40 h non traitées.","3 agents supplémentaires porteraient l'équipe à 5 agents (200 h), excédant le besoin.","Surestimation surdimensionnant l'équipe à 6 agents."]},{"id":"planning-meet-031","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quel créneau horaire de 30 minutes convient aux deux participants ?","s":"Directrice : disponible de 11 h 00 à 12 h 30. Conseiller : disponible de 10 h 30 à 11 h 45.","o":["11 h 00 à 11 h 30","10 h 30 à 11 h 00","11 h 45 à 12 h 15","11 h 30 à 12 h 00"],"a":0,"e":"La directrice et le conseiller partagent une plage commune de 11 h 00 à 11 h 45 (45 minutes disponibles). Le créneau 11 h 00 – 11 h 30 permet de réaliser la réunion de 30 minutes sans aucun conflit.","x":["Correct : intersection commune de 11 h 00 à 11 h 45, permettant une réunion de 11 h 00 à 11 h 30.","La directrice n'est pas disponible avant 11 h 00.","Le conseiller n'est plus disponible après 11 h 45.","Le créneau déborderait sur l'indisponibilité du conseiller dès 11 h 45."]},{"id":"planning-prio-032","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quelle séquence d'exécution minimise le risque de rupture de service ?","s":"À 10 h 00 : Tâche X (durée 20 min, échéance 10 h 30). Tâche Y (durée 40 min, échéance 11 h 45). Tâche Z (durée 30 min, échéance 12 h 30).","o":["Tâche X, puis Tâche Y, puis Tâche Z","Tâche Y, puis Tâche X, puis Tâche Z","Tâche Z, puis Tâche X, puis Tâche Y","Tâche X, puis Tâche Z, puis Tâche Y"],"a":0,"e":"La tâche X a l'échéance la plus critique (10 h 30). Démarrée à 10 h 00, elle se termine à 10 h 20. Enchaîner par Y (10 h 20 – 11 h 00) respecte son échéance de 11 h 45, et Z conclut à 11 h 30 avant son terme de 12 h 30.","x":["Correct : X finie à 10 h 20 (< 10h30), Y finie à 11 h 00 (< 11h45), Z finie à 11 h 30 (< 12h30).","Commencer par Y repousse la fin de X à 11 h 00, provoquant un retard de 30 minutes.","Commencer par Z fait manquer l'échéance de X dès 10 h 30.","Bien que possible, intercaler Z avant Y réduit la marge de sécurité de Y sans nécessité."]},{"id":"planning-conflit-033","f":"single_best","skill":"conflits","difficulty":2,"p":"Quel horaire d'ouverture du guichet évite toute rupture d'accueil des usagers ?","s":"Agent 1 assure la permanence de 8 h 30 à 12 h 30. L'Agent 2 prend le relais pour l'après-midi. Une passation de consignes de 15 minutes est obligatoire entre les deux agents.","o":["L'Agent 2 doit arriver au plus tard à 12 h 15.","L'Agent 2 peut arriver à 12 h 30 sans risque de rupture.","L'Agent 2 peut arriver à 12 h 45 si les usagers patientent.","L'Agent 1 doit quitter son poste à 12 h 15 pour préparer ses dossiers."],"a":0,"e":"Pour assurer la continuité sans interruption de service, la passation de 15 minutes doit s'effectuer avant le départ de l'Agent 1 fixé à 12 h 30. L'Agent 2 doit donc impérativement être en poste dès 12 h 15.","x":["Correct : 15 minutes de passation avant le départ d'Agent 1 à 12 h 30 imposent une arrivée à 12 h 15.","Arriver à 12 h 30 repousserait la fin de la passation à 12 h 45, laissant le guichet sans permanence.","Engendrerait une fermeture non autorisée du guichet de 15 minutes.","Quitter le poste à 12 h 15 interromprait prématurément le service."]},{"id":"planning-dep-034","f":"single_best","skill":"dependances","difficulty":2,"p":"Quel est le premier jour ouvré auquel le rapport final peut être soumis ?","s":"La collecte de données prend 2 jours ouvrés (lundi et mardi). Le traitement statistique requiert 1 jour ouvré dès la collecte terminée. La relecture juridique requiert 1 jour ouvré dès le traitement achevé.","o":["Vendredi","Jeudi","Mercredi","Lundi suivant"],"a":0,"e":"Collecte : jours 1 et 2 (lundi et mardi). Traitement : jour 3 (mercredi). Relecture : jour 4 (jeudi). Le rapport final est donc prêt et peut être formellement soumis dès le jour 5 (vendredi).","x":["Correct : Lundi-Mardi (Collecte), Mercredi (Traitement), Jeudi (Relecture) ; soumission possible le Vendredi.","Le jeudi est consacré à la relecture juridique, la soumission n'a lieu que le lendemain.","Le mercredi correspond seulement à l'étape intermédiaire de traitement statistique.","Délai inutilement allongé sautant le vendredi."]},{"id":"planning-agenda-035","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"Quelle est la durée totale cumulée des temps de pause autorisés sur la journée ?","s":"La journée de travail s'étend de 8 h 30 à 17 h 00. Les activités productives planifiées totalisent 7 heures et 15 minutes de travail effectif.","o":["1 heure et 15 minutes","45 minutes","1 heure","1 heure et 30 minutes"],"a":0,"e":"L'amplitude totale entre 8 h 30 et 17 h 00 représente 8 heures et 30 minutes. Le temps productif étant de 7 heures et 15 minutes, le reliquat consacré aux pauses s'élève à 8 h 30 − 7 h 15 = 1 heure et 15 minutes.","x":["Correct : amplitude globale de 8 h 30 à 17 h 00 = 8 h 30 ; 8 h 30 - 7 h 15 = 1 h 15 de pause.","Sous-estime le temps résiduel disponible.","Calcul erroné omettant le quart d'heure.","Surestimation excédant l'amplitude totale."]}],"situational":[{"id":"situational-serve-001","f":"rating","skill":"servir-client-usager","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager conteste vivement une décision de refus d'allocation, prise conformément au règlement. Vous pouvez en expliquer les motifs, mais vous n'avez pas le pouvoir de la modifier.","o":["Écouter la personne, expliquer les motifs et indiquer les voies de recours et leurs délais.","Expliquer brièvement que la décision est conforme et clore l'échange pour ne pas retarder la file.","Proposer de transmettre le dossier pour réexamen, en laissant entendre qu'une révision reste possible.","Remettre la notice écrite sur les recours et inviter la personne à la lire tranquillement chez elle."],"a":0,"e":"La meilleure réaction combine écoute, explication des motifs et information complète sur les recours, sans promesse. La notice seule informe, mais sans accompagnement ; clore l'échange ou suggérer un réexamen fictif dégrade le service.","r":[4,2,1,3],"x":["Écoute, explique et informe sur les recours : service complet sans fausse promesse.","Exact sur le fond, mais l'usager repart sans comprendre ni connaître ses droits.","Crée une fausse attente : vous n'avez pas le pouvoir de réviser la décision.","Informe correctement, mais sans explication ni écoute."]},{"id":"situational-advise-002","f":"rating","skill":"conseiller","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un collègue doit répondre aujourd'hui à un usager sur le traitement fiscal d'une subvention et vous demande conseil. Ce sujet ne relève pas de votre expertise. La référente fiscale du service est joignable dans l'heure.","o":["Donner votre meilleure estimation, en précisant qu'elle reste à confirmer par la référente.","Lui dire que ce n'est pas votre domaine et le laisser trouver lui-même le bon interlocuteur.","Reconnaître vos limites et organiser avec lui un échange rapide avec la référente.","Lui transmettre le nom et les coordonnées de la référente fiscale du service."],"a":2,"e":"Conseiller, c'est aussi reconnaître ses limites et orienter efficacement : préparer les faits et organiser le contact avec la référente garantit une réponse fiable dans le délai. Transmettre ses coordonnées aide, mais moins ; une estimation hors expertise risque de circuler comme une réponse.","r":[2,1,4,3],"x":["Une estimation hors de votre domaine risque d'être relayée comme une réponse fiable.","Respecte vos limites, mais n'aide pas votre collègue à tenir le délai.","Reconnaît vos limites et assure une réponse fiable dans le délai.","Oriente correctement, mais sans préparer l'échange ni vérifier le délai."]},{"id":"situational-serve-003","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager demande que son dossier soit traité en priorité, en invoquant une connaissance personnelle au sein de votre direction. Le règlement du service ne prévoit aucun traitement prioritaire dans son cas.","o":["Prendre ses coordonnées et lui promettre de l'appeler dès que son dossier aura été traité.","Accepter d'examiner son dossier en premier, puisque cela ne prendra que quelques minutes.","Lui suggérer de contacter directement la personne qu'il cite pour obtenir une dérogation.","Rappeler poliment que les dossiers sont traités dans l'ordre et indiquer le délai prévu."],"a":3,"e":"L'égalité de traitement des usagers interdit tout passe-droit. La réponse la plus pertinente maintient l'ordre de traitement tout en donnant une information utile (le délai). Le rappel promis est acceptable mais n'aborde pas la demande.","r":[3,1,2,4],"x":["Service courtois, mais la demande de priorité n'est pas traitée clairement.","Passe-droit contraire à l'égalité de traitement.","Encourage une démarche de faveur hors procédure.","Maintient l'égalité de traitement et informe sur le délai."]},{"id":"situational-serve-004","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Une personne appelle pour connaître l'état du dossier de son père, actuellement hospitalisé. Elle n'a pas de procuration. Les informations d'un dossier ne peuvent être communiquées qu'à son titulaire ou à une personne mandatée.","o":["Lui donner l'état du dossier, puisque le lien familial paraît évident et la situation urgente.","Refuser de communiquer toute information et mettre poliment fin à l'appel.","Expliquer que vous ne pouvez rien communiquer sans procuration et indiquer comment en obtenir une.","Proposer d'appeler son père à l'hôpital pour faire le point directement avec lui."],"a":2,"e":"La confidentialité s'impose, mais servir l'usager suppose d'expliquer la règle et d'indiquer une solution (la procuration). Contacter le titulaire est possible mais plus lourd ; refuser sans solution respecte la règle sans aider.","r":[1,2,4,3],"x":["Viole la confidentialité du dossier.","Respecte la règle, mais laisse la personne sans solution.","Respecte la règle et donne une solution concrète.","Respecte la confidentialité, mais l'appel à l'hôpital peut être intrusif."]},{"id":"situational-serve-005","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager demande une dispense de pièce justificative pour un dossier urgent. Vous n'êtes pas habilité à accorder cette dispense ; votre responsable l'est.","o":["L'inviter à adresser lui-même un courrier à votre responsable, en lui donnant l'adresse.","Préciser que vous n'êtes pas habilité, puis transmettre sa demande écrite au responsable.","Accorder la dispense oralement, la situation vous paraissant de bonne foi.","Lui répondre que la règle ne prévoit aucune exception et clore la demande."],"a":1,"e":"Le respect de la légalité n'empêche pas d'accompagner l'usager : transmettre une demande documentée à l'autorité compétente est la meilleure réponse. Orienter vers un courrier est utile mais plus lent ; décider sans habilitation est exclu.","r":[3,4,1,2],"x":["Oriente vers la bonne personne, mais laisse l'usager faire seul la démarche.","Respecte votre champ de compétence et fait avancer la demande.","Décision prise sans habilitation.","Affirme une règle que vous ne pouvez pas trancher, sans transmettre."]},{"id":"situational-advise-006","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"En réunion de projet, deux directions partenaires défendent deux solutions techniques différentes. Votre responsable vous demande une note pour éclairer sa décision.","o":["Recommander la solution de la direction la plus influente, pour faciliter son adoption.","Comparer les options sur des critères objectifs et formuler une recommandation motivée.","Présenter les deux solutions telles que chaque direction les décrit, sans analyse propre.","Proposer d'abord un atelier commun aux deux directions, puis rédiger l'analyse comparative."],"a":1,"e":"Le rôle de conseil consiste à fournir une analyse neutre, documentée et conclusive. L'atelier peut enrichir l'analyse mais retarde la note ; reprendre les positions sans analyse n'éclaire pas la décision.","r":[1,4,2,3],"x":["Critère d'influence et non de fond : conseil partial.","Analyse objective et recommandation utile au décideur.","Neutre, mais sans valeur ajoutée pour la décision.","Démarche constructive, mais qui retarde la note demandée."]},{"id":"situational-advise-007","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Votre responsable vous demande de publier dès demain un cahier des charges. Vous y repérez une clause ambiguë qui pourrait provoquer un contentieux lors de l'attribution du marché.","o":["Publier comme demandé et signaler l'ambiguïté une fois la publication effectuée.","Demander l'avis du service juridique avant toute action, quitte à décaler la publication de plusieurs semaines.","Corriger vous-même la clause et publier sans attendre de validation.","Signaler le risque par écrit à votre responsable et proposer une formulation corrigée prête à valider."],"a":3,"e":"Conseiller, c'est alerter sur le risque et proposer une solution qui permet de tenir le délai. Saisir le juridique est prudent mais disproportionné ici ; publier en l'état ou corriger seul contourne la décision du responsable.","r":[2,3,1,4],"x":["Le risque est signalé trop tard pour être évité.","Prudent, mais le retard est disproportionné sans en parler au responsable.","Modification sans validation de la personne qui décide.","Alerte à temps et solution prête : le responsable peut décider vite."]},{"id":"situational-serve-008","f":"rating","skill":"servir-client-usager","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager peu à l'aise avec l'informatique n'arrive pas à faire sa démarche en ligne. Un espace d'aide numérique, avec un agent disponible, se trouve dans le bâtiment.","o":["L'accompagner vers l'espace d'aide numérique pour réaliser la démarche avec lui, étape par étape.","Faire la démarche à sa place en utilisant ses identifiants personnels, pour gagner du temps.","Lui remettre le guide pas à pas et l'inviter à revenir si un problème persiste.","Lui proposer un rendez-vous avec un conseiller numérique dans le courant de la semaine."],"a":0,"e":"L'accompagnement immédiat sur place permet d'aboutir tout en rendant l'usager plus autonome. Un rendez-vous est utile mais diffère la démarche ; utiliser ses identifiants pose un problème de sécurité.","r":[4,1,2,3],"x":["Aide immédiate et adaptée, qui renforce l'autonomie.","Utiliser les identifiants d'autrui pose un problème de sécurité.","Aide minimale pour une personne déjà en difficulté.","Solution valable, mais elle retarde la démarche."]},{"id":"situational-advise-009","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Votre directrice vous demande quel indicateur retenir dans le rapport annuel pour illustrer la baisse des délais. L'indicateur A, plus favorable, exclut les dossiers incomplets. L'indicateur B couvre tous les dossiers mais montre une baisse plus modeste.","o":["Recommander l'indicateur A, plus favorable, sans détailler son périmètre exact.","Recommander l'indicateur B, sans mentionner l'existence de l'indicateur A.","Présenter les deux indicateurs et leurs limites, puis recommander B en justifiant ce choix.","Recommander l'indicateur A, en précisant son périmètre dans une note de bas de page."],"a":2,"e":"Un bon conseil éclaire complètement la décision : il présente les options, leurs limites et une recommandation motivée. Mentionner le périmètre en note rend A acceptable ; masquer une option ou un périmètre prive la directrice d'informations utiles.","r":[1,2,4,3],"x":["Le périmètre caché peut induire les lecteurs en erreur.","Choix défendable, mais la directrice n'a pas toutes les options.","Transparence complète et recommandation motivée.","Transparent, mais l'information essentielle reste peu visible."]},{"id":"situational-serve-010","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager s'énerve car son dossier ne peut pas être enregistré : le système informatique est en panne depuis une heure, pour une durée inconnue.","o":["Lui demander de revenir plus tard, le système étant indisponible pour une durée inconnue.","Lui expliquer que la panne relève du service informatique et que vous n'y pouvez rien.","Lui proposer de faire la démarche en ligne depuis chez lui, une fois le système rétabli.","Reconnaître la gêne, expliquer la panne et proposer de le rappeler dès le rétablissement."],"a":3,"e":"Reconnaître la gêne et garantir un suivi personnalisé apaise la situation et sécurise la démarche. Proposer la démarche en ligne est praticable mais laisse l'usager seul ; renvoyer la responsabilité au service informatique aggrave la tension.","r":[2,1,3,4],"x":["Exact, mais l'usager repart sans solution ni suivi.","Se désolidarise de l'administration et laisse l'usager sans solution.","Solution praticable, mais sans suivi personnalisé ni prise en compte de son énervement.","Reconnaît la gêne, informe et garantit un suivi."]},{"id":"situational-serve-011","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Une personne âgée se présente au guichet, désemparée car elle ne parvient pas à utiliser l'application mobile obligatoire pour renouveler son allocation de chauffage. Le guichet dispose d'un poste informatique d'accompagnement.","o":["L'inviter à s'installer au poste d'accompagnement et l'assister pas à pas pour saisir sa demande en ligne.","Lui indiquer qu'elle doit demander à un proche de faire la démarche sur smartphone à son domicile.","Prendre ses identifiants personnels et compléter intégralement la démarche à sa place pour gagner du temps.","Lui imprimer un formulaire papier non officiel qu'elle remplira sur place et qui sera saisi ultérieurement."],"a":0,"e":"La posture optimale du service public (note 4) consiste à accompagner les usagers vulnérables vers l'autonomie numérique grâce aux moyens dédiés (poste d'accompagnement), sans enfreindre la sécurité des données (ne jamais utiliser les identifiants d'autrui) ni créer de démarches parallèles non réglementaires.","r":[4,2,1,2],"x":["Très approprié (4) : inclusion numérique bienveillante favorisant l'autonomie de l'usager dans un cadre sécurisé.","Inapproprié (2) : renvoi vers des tiers sans solution interne alors qu'un accompagnement sur place est possible.","Très inapproprié (1) : manipulation des identifiants personnels d'un usager enfreignant les règles de sécurité.","Inapproprié (2) : utilisation d'une procédure non homologuée risquant d'invalider la demande de l'usager."]},{"id":"situational-advise-012","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un jeune collègue chargé d'études doit animer une réunion avec des représentants syndicaux sur un projet de refonte des horaires. Il craint des tensions et vous demande comment structurer son intervention.","o":["Lui conseiller de présenter d'abord les constats factuels et objectifs, puis d'ouvrir un échange structuré sur les besoins exprimés.","Lui recommander d'imposer fermement le calendrier ministériel dès le début pour couper court à toute discussion.","Lui suggérer d'annuler la réunion et de communiquer la décision unilatéralement par note de service écrite.","Lui proposer de faire une intervention informelle sans ordre du jour pour éviter de formaliser les désaccords."],"a":0,"e":"Le conseil professionnel (note 4) encourage une méthode rigoureuse : baser l'échange sur des éléments factuels partagés, donner la parole de manière cadrée et écouter les observations pour coconstruire la mise en œuvre.","r":[4,1,1,2],"x":["Très approprié (4) : démarche constructive et objective favorisant le dialogue social tout en gardant un cadre professionnel.","Très inapproprié (1) : posture autoritaire qui envenime le conflit et rompt la confiance avec les partenaires sociaux.","Très inapproprié (1) : déni de concertation contraire aux principes d'administration moderne et participative.","Inapproprié (2) : absence de cadre qui décrédibilise l'administration et risque de rendre les échanges stériles."]},{"id":"situational-serve-013","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un journaliste demande par téléphone la communication immédiate du projet de rapport d'audit interne sur la gestion d'un établissement public, document non encore validé par la commission de tutelle.","o":["Lui expliquer courtoisement que le rapport est un document préparatoire non communicable et l'orienter vers le service de presse ministériel.","Lui envoyer immédiatement une copie par courriel sous couvert d'anonymat pour favoriser la transparence publique.","Refuser sèchement de lui répondre et raccrocher sans lui donner la moindre explication.","Lui promettre une transmission exclusive dès le lendemain sans en référer à votre hiérarchie."],"a":0,"e":"Les documents préparatoires ne sont pas communicables tant que la décision définitive n'est pas adoptée. L'attitude correcte (note 4) consiste à faire preuve de pédagogie sur l'état juridique du document et à réorienter vers le service officiel habilité.","r":[4,1,1,2],"x":["Très approprié (4) : respect du secret professionnel et des règles de communicabilité des actes préparatoires avec orientation adaptée.","Très inapproprié (1) : fuite délibérée d'un document non officiel constituant une faute professionnelle grave.","Très inapproprié (1) : incivilité et manquement au devoir élémentaire de courtoisie du fonctionnaire.","Inapproprié (2) : promesse illégale et violation des prérogatives de la hiérarchie et du service de communication."]},{"id":"situational-advise-014","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Votre chef de service souhaite accélérer l'octroi d'un marché public avant la fin de l'exercice budgétaire pour éviter la perte de crédits, en omettant l'avis obligatoire de la commission des marchés.","o":["Alerter le chef de service par écrit sur le risque d'illégalité et de nullité du marché, et proposer un calendrier de passation accéléré mais légal.","Valider la procédure sans réserve pour obéir aux instructions hiérarchiques et préserver les crédits budgétaires.","Dénoncer immédiatement votre supérieur hiérarchique au parquet sans lui faire part au préalable de l'irrégularité.","Refuser d'exécuter la tâche oralement en menaçant de vous mettre en grève."],"a":0,"e":"L'agent public de catégorie A1 a un devoir de conseil technique : il doit formuler par écrit une mise en garde loyale sur les risques juridiques (nullité du marché, engagement de responsabilité) tout en étant force de proposition pour rechercher une issue légale dans les délais.","r":[4,1,1,2],"x":["Très approprié (4) : devoir de conseil vigilant protégeant l'administration contre l'illégalité tout en proposant une solution constructive.","Très inapproprié (1) : complicité d'une irrégularité juridique majeure contraire au devoir de probité.","Très inapproprié (1) : rupture disproportionnée de la voie hiérarchique sans démarche préalable de clarification interne.","Inapproprié (2) : réaction émotionnelle conflictuelle non conforme à la déontologie administrative."]},{"id":"situational-serve-015","f":"rating","skill":"servir-client-usager","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager affirme avec véhémence au guichet qu'il a déposé une pièce justificative essentielle il y a trois jours, mais celle-ci n'apparaît nulle part dans son dossier informatique.","o":["Vérifier le bac des courriers en cours de numérisation et l'aider à réimprimer la pièce si possible.","Lui soutenir qu'il se trompe et refuser formellement tout examen de son dossier sans la pièce originale.","Valider immédiatement sa demande sans la pièce requise pour désamorcer son mécontentement au guichet.","L'orienter vers le commissariat de police pour signaler la perte de sa pièce justificative déposée."],"a":0,"e":"Face à un litige de transmission, l'agent doit faire preuve d'empathie sans présumer de la faute de l'usager, vérifier les points d'attente internes (numérisation) et lui faciliter la fourniture immédiate d'une copie de substitution pour débloquer son dossier.","r":[4,2,1,2],"x":["Très approprié (4) : posture de recherche active de solution sans accusation mutuelle, conciliant bienveillance et rigueur.","Inapproprié (2) : mise en cause agressive de la bonne foi de l'usager bloquant la relation de service.","Très inapproprié (1) : dispense de justificatif légal sans fondement exposant le service à une décision illégale.","Inapproprié (2) : démarche absurde et disproportionnée qui ne règle pas le problème de dossier."]},{"id":"situational-serve-016","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez l'adéquation de chacune des réactions suivantes face à la situation décrite.","s":"Un usager se présente au guichet en exigeant le traitement immédiat de son attestation, expliquant qu'il a un avion à prendre dans deux heures. La procédure standard impose une vérification de sécurité de 24 heures.","o":["Lui expliquer posément la contrainte réglementaire de 24 heures tout en vérifiant si un traitement accéléré est prévu pour urgence avérée.","Lui délivrer immédiatement l'attestation sans vérification pour lui éviter de manquer son vol.","L'éconduire froidement en lui reprochant son manque d'anticipation et d'organisation personnelle.","Vérifier la complétude de son dossier pour engager le contrôle sans délai et lui proposer l'envoi dématérialisé dès validation."],"a":0,"e":"Face à une demande urgente d'usager, le fonctionnaire doit maintenir un accueil courtois et impartial, respecter scrupuleusement les exigences réglementaires de contrôle, et rechercher des solutions constructives légales (accélération si prévue, délivrance numérique immédiate dès validation).","r":[4,1,1,3],"x":["Très approprié : concilie écoute active, courtoisie et recherche des voies légales sans enfreindre la règle.","Très inapproprié : viole la procédure de sécurité obligatoire et engage la responsabilité de l'administration.","Très inapproprié : manque manifeste de courtoisie et attitude agressive contraire au devoir d'accueil.","Plutôt approprié : optimise le processus dans le cadre légal et offre une solution de continuité numérique."]},{"id":"situational-advise-017","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez la pertinence de chaque conseil formulé par l'agent public.","s":"Un usager sollicite votre avis personnel sur l'opportunité de contester en justice une décision administrative de refus prise par un autre ministère.","o":["Lui exposer objectivement les voies et délais de recours légaux existants sans émettre d'avis subjectif sur l'issue judiciaire.","Lui conseiller vivement d'attaquer la décision en lui affirmant qu'il gagnera son procès à coup sûr.","Refuser tout dialogue sous prétexte que le dossier relève d'un autre ministère.","L'orienter vers les permanences juridiques gratuites ou le Médiateur pour une analyse spécialisée et indépendante de sa situation."],"a":0,"e":"Le devoir de conseil de l'agent public exige une neutralité absolue et le respect de son périmètre de compétence. Il doit fournir les informations procédurales objectives (délais, recours) et orienter vers les professionnels du droit sans jamais spéculer sur une issue judiciaire.","r":[4,1,1,3],"x":["Très approprié : conseil neutre, factuel et centré sur l'information légale sans prise de position partisane.","Très inapproprié : manque total de réserve, promesse irréaliste et dépassement flagrant de compétence.","Très inapproprié : refus d'information élémentaire contraire au rôle de service public et d'orientation citoyenne.","Plutôt approprié : orientation vers les organismes compétents assurant un accompagnement indépendant."]},{"id":"situational-serve-018","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque attitude face à un usager vulnérable.","s":"Une personne âgée se présente désemparée au guichet car elle ne parvient pas à télédéclarer son formulaire sur la plateforme numérique obligatoire.","o":["L'accompagner pas à pas à la borne numérique publique de l'administration pour lui montrer la démarche avec bienveillance.","Lui rétorquer que l'administration est désormais 100 % numérique et qu'elle doit se débrouiller par elle-même.","Lui proposer un rendez-vous personnalisé d'assistance ou lui fournir un formulaire papier alternatif si la réglementation l'autorise.","Prendre ses identifiants secrets personnels pour remplir la déclaration à sa place sur son compte privé."],"a":0,"e":"L'administration moderne doit lutter contre l'illectronisme par un accompagnement humain bienveillant (médiation numérique, assistance guidée) sans jamais enfreindre les règles de sécurité relatives aux identifiants personnels des citoyens.","r":[4,1,3,1],"x":["Très approprié : réponse exemplaire d'inclusion numérique garantissant l'accès universel au service public.","Très inapproprié : rejet discriminatoire violant l'obligation d'accessibilité et de continuité du service public.","Plutôt approprié : solution d'accompagnement formelle respectant le cadre réglementaire d'assistance.","Très inapproprié : grave manquement aux règles élémentaires de sécurité informatique et de protection des données."]},{"id":"situational-advise-019","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez la pertinence de chaque modalité de conseil face à une incertitude réglementaire.","s":"Une entreprise vous sollicite pour savoir si son nouveau procédé industriel entre dans le champ d'application d'une taxe environnementale récemment votée mais dont le règlement d'application n'est pas encore publié.","o":["Lui exposer l'état actuel des textes officiels, réserver votre réponse sur les points en suspens et solliciter une note de cadrage ministérielle.","Lui garantir par écrit une exonération totale définitive pour rassurer immédiatement l'investisseur.","Rejeter d'office la demande de l'entreprise en lui demandant de ne pas importuner les services ministériels.","Lui indiquer les critères probables issus des débats parlementaires tout en précisant expressément leur caractère non opposable."],"a":0,"e":"En cas de vide ou d'attente d'un décret d'application, le conseiller public doit faire preuve d'une prudence juridique stricte. Il informe sur les bases existantes, réserve l'interprétation officielle auprès de la direction compétente et s'abstient de tout engagement prématuré.","r":[4,1,1,3],"x":["Très approprié : démarche rigoureuse préservant la sécurité juridique de l'administration et de l'usager.","Très inapproprié : engagement illégal engageant la responsabilité financière de l'État sans texte d'application.","Très inapproprié : mépris du monde économique contraire aux missions de conseil et d'accueil de l'administration.","Plutôt approprié : information contextuelle utile assortie de la réserve juridique indispensable sur la non-opposabilité."]},{"id":"situational-serve-020","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez chaque comportement d'accueil face à une situation de tension au guichet.","s":"Un administré hausse le ton et accuse nominativement un de vos collègues d'avoir égaré son dossier d'aide au logement il y a deux semaines.","o":["L'inviter calmement à s'asseoir dans un espace discret, écouter sa réclamation sans accuser le collègue et vérifier immédiatement l'historique informatique du dossier.","Prendre immédiatement la défense agressive de votre collègue en haussant le ton à votre tour contre l'usager.","Donner immédiatement raison à l'usager devant tout le monde en dénigrant ouvertement les compétences de votre collègue.","Lui expliquer le processus de reconstitution rapide de dossier si la perte est confirmée et lui remettre un accusé de réception horodaté."],"a":0,"e":"Face à une accusation visant un collègue, l'agent doit concilier écoute empathique de l'usager, désescalade relationnelle dans un cadre calme, loyauté envers ses pairs et vérification factuelle impartiale dans les systèmes de gestion.","r":[4,1,1,3],"x":["Très approprié : désamorce le conflit, isole la tension, protège l'esprit d'équipe et engage la vérification objective.","Très inapproprié : escalade de l'agressivité violant les principes d'accueil professionnel et de retenue.","Très inapproprié : manquement grave au devoir de confraternité et décrédibilisation publique du service.","Plutôt approprié : orientation constructive vers la résolution matérielle du problème avec formalisation administrative."]},{"id":"situational-advise-021","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez la pertinence de chaque recommandation d'un agent public.","s":"Un citoyen ne comprend pas les motifs du rejet partiel de sa demande d'allocation familiale et vous demande ce qu'il peut faire concrètement.","o":["Reprendre avec lui les critères légaux point par point pour expliciter de manière claire et intelligible les fondements de la décision.","Lui répondre que les décisions de l'administration ne se discutent pas et qu'il n'a qu'à relire la notification.","Lui préciser la procédure de recours gracieux auprès de la direction ainsi que le délai légal imparti pour le formuler.","Rédiger vous-même la lettre de recours de l'usager pour contester la décision de votre propre administration."],"a":0,"e":"Le devoir de conseil impose d'expliquer avec pédagogie les motivations d'un refus et d'éclairer l'usager sur les voies de recours légales, sans pour autant se substituer à lui dans la rédaction d'un recours contentieux.","r":[4,1,3,1],"x":["Très approprié : pédagogie administrative remarquable renforçant la transparence et la compréhension citoyenne.","Très inapproprié : posture autoritaire et fermée bafouant le devoir d'explication des décisions administratives.","Plutôt approprié : information juridique indispensable permettant à l'usager d'exercer ses droits réguliers.","Très inapproprié : conflit d'intérêts et confusion des rôles (l'agent public ne peut se substituer au requérant)."]},{"id":"situational-serve-022","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez l'adéquation de chaque attitude d'accueil multilingue.","s":"Dans une administration luxembourgeoise, un usager résident étranger ne s'exprime qu'en anglais et éprouve des difficultés à comprendre le formulaire officiel rédigé en français.","o":["Mobiliser vos compétences en anglais pour lui expliciter les rubriques principales et lui remettre la documentation explicative multilingue disponible.","Exiger sur un ton comminatoire qu'il revienne avec un interprète assermenté pour pouvoir être accueilli.","Refuser catégoriquement de prononcer un mot d'anglais au nom de la stricte réglementation linguistique.","Faire appel à un collègue disponible du service bilingue pour fluidifier l'échange et sécuriser la complétude du dossier."],"a":0,"e":"Au Luxembourg, le sens du service au client-usager implique de faciliter la compréhension des démarches grâce au multilinguisme pratique des équipes, dans le respect de l'équité de traitement et de la bienveillance administrative.","r":[4,1,1,3],"x":["Très approprié : pragmatisme, sens du service public et facilitation de l'accès aux démarches administratives.","Très inapproprié : rigidité disproportionnée et accueil hostile portant atteinte à la qualité de service.","Très inapproprié : manque manifeste de courtoisie et d'adaptation au contexte multiculturel du pays.","Plutôt approprié : excellente collaboration interne permettant de résoudre la difficulté sans ralentir le service."]},{"id":"situational-advise-023","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez chaque posture de conseil déontologique face à un cadeau d'entreprise.","s":"À l'issue de l'instruction favorable d'un dossier complexe, le dirigeant d'une société privée reconnaissant vous dépose un panier gastronomique d'une valeur de 150 euros.","o":["Refuser avec courtoisie en rappelant le code de déontologie des agents de l'État qui proscrit tout avantage personnel en lien avec les fonctions.","Accepter discrètement le cadeau pour ne pas vexer ce partenaire économique de l'État.","Partager le panier avec toute l'équipe dans la salle de repos sans en informer votre hiérarchie.","Informer votre supérieur hiérarchique du dépôt du panier et solliciter la restitution formelle ou son don à une œuvre caritative reconnue."],"a":0,"e":"Les règles de déontologie publique interdisent formellement aux agents de recevoir des gratifications de valeur de la part d'usagers ou d'entreprises. Le refus courtois mais ferme ou l'arbitrage transparent de la hiérarchie sont les seules voies conformes.","r":[4,1,1,3],"x":["Très approprié : rectitude déontologique exemplaire, clarté et préservation de l'intégrité de la fonction publique.","Très inapproprié : manquement déontologique caractérisé pouvant constituer une faute disciplinaire grave.","Très inapproprié : le partage interne ne purge pas l'irrégularité de l'acceptation d'un avantage indu.","Plutôt approprié : transparence hiérarchique totale assurant un traitement institutionnel conforme et désintéressé."]},{"id":"situational-serve-024","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez chaque réaction face à une erreur administrative avérée.","s":"Vous découvrez qu'en raison d'un bogue informatique temporaire, un courrier erroné réclamant indûment une pièce justificative déjà fournie a été envoyé à 50 usagers.","o":["Informer immédiatement la hiérarchie, adresser un rectificatif explicatif d'excuse aux 50 usagers et valider leurs dossiers sans délai supplémentaire.","Ignorer l'incident en espérant que la majorité des usagers renverra une seconde fois la pièce sans protester.","Attendre que chaque usager se manifeste individuellement au guichet pour rectifier au cas par cas.","Rassurer au téléphone les usagers qui appellent en enregistrant la régularisation immédiate sur leur dossier informatique."],"a":0,"e":"Le service à l'usager commande une transparence proactive en cas d'erreur de l'administration : un message rectificatif global avec excuses professionnelles et validation automatique des droits rétablit la confiance légitime des administrés.","r":[4,1,1,3],"x":["Très approprié : proactivité, transparence, assomption de l'erreur administrative et respect de la confiance du public.","Très inapproprié : passivité coupable surchargeant indûment les administrés pour masquer une défaillance interne.","Très inapproprié : gestion passive et inéquitable pénalisant les usagers qui n'osent pas réclamer.","Plutôt approprié : réaction positive et aidante au contact individuel, mais insuffisante à l'échelle du groupe impacté."]},{"id":"situational-advise-025","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez chaque démarche de conseil auprès d'un usager en situation de précarité.","s":"Un administré en grande difficulté financière sollicite une aide d'urgence pour laquelle il ne remplit pas l'ensemble des critères d'attribution légale.","o":["Lui expliquer avec tact les limites du dispositif sollicité et l'orienter activement vers l'office social compétent ou les aides complémentaires existantes.","Lui promettre verbalement l'octroi de l'aide en forçant les critères de saisie informatique à son insu.","Lui notifier un rejet brutal sans aucune explication ni recherche de relais d'accompagnement social.","Lui remettre la liste coordonnée des structures d'aide sociale de sa commune et prendre contact avec un assistant social référent avec son accord."],"a":0,"e":"Conseiller un citoyen en précarité nécessite d'allier rigueur déontologique (interdiction d'altérer les critères légaux) et empathie active (orientation vers les dispositifs d'assistance sociale adaptés).","r":[4,1,1,3],"x":["Très approprié : humanité, rigueur réglementaire et orientation sociale constructive sans fausse promesse.","Très inapproprié : fraude administrative délibérée violant la loi sous couvert de compassion personnelle.","Très inapproprié : inhumanité et défaillance du rôle fondamental d'orientation sociale du service public.","Plutôt approprié : excellente démarche partenariale facilitant l'accès effectif aux droits sociaux territoriaux."]},{"id":"situational-serve-026","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la qualité de prise en charge d'un usager mécontent au téléphone.","s":"Un citoyen excédé vous appelle car sa demande de prime n'a pas été traitée après six semaines d'attente, alors que le délai indicatif annoncé est de quatre semaines.","o":["Écouter attentivement son mécontentement sans lui couper la parole, consulter immédiatement l'état du dossier et lui communiquer une date prévisionnelle fiable.","Lui raccrocher immédiatement au nez au motif qu'il manifeste un agacement verbal excessif.","Lui répondre que les agents font ce qu'ils peuvent et qu'il n'est pas le seul à attendre dans le pays.","Identifier le point de blocage précis dans le dossier, le débloquer si cela relève de vos attributions et le rappeler personnellement dès finalisation."],"a":0,"e":"Face au retard et à la frustration d'un usager, la posture requise consiste en une écoute calme et respectueuse, l'analyse factuelle de l'origine du délai et un engagement clair et réaliste sur le traitement de la demande.","r":[4,1,1,3],"x":["Très approprié : écoute active, courtoisie, apaisement de la relation et information transparente sur le délai réel.","Très inapproprié : faute professionnelle grave rompant unilatéralement la communication avec l'usager.","Très inapproprié : réponse infantilisante et méprisante aggravant le sentiment d'injustice de l'administré.","Plutôt approprié : engagement professionnel proactif et sens aigu de la responsabilité individuelle au service de l'usager."]},{"id":"situational-advise-027","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez chaque conseil formulé à un collaborateur face à un risque de conflit d'intérêts.","s":"Un collègue gestionnaire de dossiers d'attribution de marchés publics vous confie que l'entreprise de son beau-frère a déposé une offre pour un marché dont il a la charge.","o":["Lui conseiller de déclarer immédiatement ce lien familial à sa hiérarchie et de solliciter formellement son déport de cette commission d'évaluation.","Lui recommander de ne rien dire pour ne pas éveiller de soupçons inutiles si son jugement demeure impartial.","Lui suggérer de favoriser discrètement l'offre de son parent pour soutenir l'économie familiale.","L'inviter à consulter sans délai le référent déontologue de votre ministère pour sécuriser la procédure d'attribution."],"a":0,"e":"En matière de commande publique, tout lien d'intérêt personnel ou familial avec un soumissionnaire impose une déclaration immédiate et un déport strict pour prévenir toute suspicion de favoritisme ou de conflit d'intérêts.","r":[4,1,1,3],"x":["Très approprié : mesure de déport impérative protégeant la légalité du marché public et l'intégrité de l'agent.","Très inapproprié : conseil dangereux exposant l'agent à une qualification pénale de prise illégale d'intérêts.","Très inapproprié : incitation directe à la commission d'un délit de favoritisme pénalement répréhensible.","Plutôt approprié : recours au référent institutionnel garantissant un conseil d'expert indépendant et formel."]},{"id":"situational-serve-028","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez chaque comportement d'accueil en situation d'affluence au guichet.","s":"À 11 h 45, alors que le guichet ferme normalement à 12 h 00, une dizaine d'usagers attendent encore dans le hall en raison d'une panne réseau intervenue le matin.","o":["Informer avec courtoisie la file d'attente de la situation, évaluer les demandes prioritaires et prolonger l'accueil pour traiter les démarches urgentes engagées.","Baisser le rideau métallique à midi pile sans un mot en refusant de prendre en charge les usagers restants.","Prendre les coordonnées et l'objet des démarches des usagers en attente pour leur proposer un créneau garanti dès le début d'après-midi.","Renvoyer tous les usagers vers le site web sans s'assurer s'ils disposent des moyens d'effectuer la démarche en ligne."],"a":0,"e":"Lorsqu'un dysfonctionnement technique imputable à l'administration retarde les usagers, le service public doit faire preuve de souplesse, de communication claire et d'aménagements raisonnables pour honorer son obligation d'accueil.","r":[4,1,3,1],"x":["Très approprié : sens des responsabilités, adaptation aux aléas techniques internes et respect des citoyens.","Très inapproprié : comportement rigide et irrespectueux ignorant l'aléa matériel subi par les usagers.","Plutôt approprié : organisation pragmatique offrant une solution alternative garantie et individualisée.","Très inapproprié : rejet expéditif méconnaissant les contraintes réelles des usagers présents."]},{"id":"situational-advise-029","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez la pertinence de chaque recommandation d'un agent public.","s":"Un citoyen hésite entre deux formulaires fiscaux pour déclarer un revenu accessoire perçu à l'étranger et vous sollicite pour faire le bon choix déclaratif.","o":["Lui expliquer précisément la notice fiscale et les critères distinctifs de chaque formulaire sans vous substituer à son choix déclaratif.","Lui conseiller de dissimuler ce revenu à l'étranger pour échapper à toute imposition complémentaire.","Lui désigner un formulaire au hasard sans vérifier les conventions bilatérales pour écourter le rendez-vous.","Lui fournir le guide pratique de fiscalité internationale et l'orienter vers la division spécialisée des non-résidents si nécessaire."],"a":0,"e":"Le fonctionnaire doit guider l'usager dans la compréhension des critères juridiques et des notices explicatives, tout en lui laissant la responsabilité de sa déclaration fiscale et en proscrivant toute incitation à la fraude.","r":[4,1,1,3],"x":["Très approprié : conseil explicatif rigoureux respectant l'autonomie et la responsabilité déclarative de l'usager.","Très inapproprié : incitation délibérée à la fraude fiscale bafouant l'honneur et la légalité républicaine.","Très inapproprié : désinvolture professionnelle coupable pouvant induire l'usager en erreur fiscale grave.","Plutôt approprié : mise à disposition d'outils d'information officiels et orientation vers le service compétent."]},{"id":"situational-serve-030","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez chaque modalité de traitement d'une réclamation d'usager.","s":"Un usager vous transmet une réclamation écrite affirmant qu'un agent d'accueil lui a manqué de respect la veille au guichet.","o":["Accuser réception de sa réclamation par écrit, transmettre les faits à la hiérarchie pour examen contradictoire et lui garantir une réponse motivée sous 15 jours.","Déchirer la lettre de réclamation pour protéger la réputation du service et étouffer l'incident.","Répondre avec agressivité à l'usager en lui interdisant désormais l'accès aux locaux administratifs.","Entendre avec bienveillance l'usager par téléphone pour consigner sa version détaillée tout en préservant la présomption de régularité du service."],"a":0,"e":"Toute réclamation d'usager doit faire l'objet d'un accusé de réception formel, d'une instruction équitable et contradictoire par l'autorité hiérarchique, et d'une réponse motivée dans un délai prévisible.","r":[4,1,1,3],"x":["Très approprié : traitement procédural exemplaire alliant écoute citoyenne, respect du contradictoire et engagement formel.","Très inapproprié : destruction illégale d'un document administratif et opacité contraire aux normes de transparence.","Très inapproprié : abus d'autorité intolérable bafouant les droits fondamentaux des usagers.","Plutôt approprié : démarche d'écoute attentive permettant d'éclairer l'instruction administrative de la réclamation."]},{"id":"situational-advise-031","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez chaque posture de conseil lors d'une sollicitation par la presse.","s":"Un journaliste vous contacte directement sur votre ligne professionnelle pour recueillir votre avis sur une polémique relative à la gestion d'un dossier sensible de votre direction.","o":["Lui rappeler courtoisement le devoir de réserve de l'agent public et l'orienter sans délai vers le service de communication ministériel officiel.","Lui livrer sous le manteau des détails internes sensibles en exigeant son anonymat journalistique.","Lui raccrocher au nez en l'injuriant pour avoir osé vous déranger durant votre travail.","Lui indiquer les données publiques déjà communiquées dans les communiqués officiels en vous abstenant de tout commentaire personnel."],"a":0,"e":"Les relations avec les médias sont strictement encadrées dans la fonction publique. L'agent doit observer un devoir de réserve scrupuleux, s'abstenir de tout commentaire personnel et orienter le journaliste vers le porte-parole officiel du ministère.","r":[4,1,1,3],"x":["Très approprié : respect rigoureux du devoir de réserve et orientation vers les canaux habilités de communication publique.","Très inapproprié : violation caractérisée du secret professionnel et manquement lourd à l'obligation de discrétion.","Très inapproprié : attitude hostile dégradant l'image institutionnelle de l'administration auprès des médias.","Plutôt approprié : rappel factuel d'éléments déjà rendus publics sans franchir les limites du droit de réserve."]},{"id":"situational-serve-032","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez chaque réaction face à une demande formulée hors compétences.","s":"Un citoyen se présente à votre guichet communal pour solliciter un permis de chasse, démarche qui relève exclusivement d'une administration d'État (Environnement).","o":["Lui expliquer avec courtoisie le partage des compétences et lui fournir l'adresse exacte, le site internet et les horaires du service compétent.","L'éconduire sèchement en lui disant que la commune n'a rien à voir avec ses activités de loisirs.","Prendre son dossier et ses pièces en lui promettant que vous vous en occuperez vous-même sans en avoir le pouvoir.","Lui imprimer le formulaire officiel de l'administration d'État et lui indiquer les pièces requises pour préparer son dépôt."],"a":0,"e":"Même face à une démarche ne relevant pas de son autorité, l'agent public a un devoir d'accueil et d'orientation : il informe le citoyen sur le service compétent et lui fournit les coordonnées utiles sans créer d'engagements illégitimes.","r":[4,1,1,3],"x":["Très approprié : orientation citoyenne claire, courtoise et efficace illustrant le principe de guichet unique relationnel.","Très inapproprié : accueil méprisant renvoyant une image dégradée de l'administration publique.","Très inapproprié : promesse illégitime générant une fausse attente et un retard préjudiciable pour l'administré.","Plutôt approprié : aide concrète et utile facilitant les démarches du citoyen auprès du bon organisme."]},{"id":"situational-advise-033","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez chaque posture de conseil face à une tentative de contournement procédural.","s":"Une connaissance personnelle vous sollicite pour faire passer en priorité le dossier de permis de construire de son fils avant la commission municipale de demain.","o":["Lui rappeler avec fermeté et courtoisie le principe constitutionnel d'égalité de traitement des usagers interdisant tout passe-droit.","Accepter avec empressement pour faire plaisir à votre relation personnelle en passant outre le registre chronologique.","Exiger une contrepartie financière ou un service personnel en échange de votre intervention prioritaire.","Lui expliquer le fonctionnement impartial de l'ordre d'instruction et lui proposer de vérifier l'état d'avancement régulier du dossier."],"a":0,"e":"Le principe fondamental d'égalité de traitement devant le service public proscrit tout traitement préférentiel motivé par des liens privés. L'agent doit opposer un refus sans équivoque en rappelant les règles d'instruction impartiale.","r":[4,1,1,3],"x":["Très approprié : réaffirmation exemplaire de l'éthique républicaine et de l'égalité d'accès des citoyens aux services publics.","Très inapproprié : rupture caractérisée de l'égalité des usagers et favoritisme administratif injustifiable.","Très inapproprié : comportement délictuel de corruption passive constitutive d'une infraction pénale gravissime.","Plutôt approprié : pédagogie administrative rappelant la règle d'impartialité tout en apportant une réponse factuelle légale."]},{"id":"situational-serve-034","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez chaque attitude d'accueil face à un usager sourd ou malentendant.","s":"Un citoyen sourd se présente au guichet pour une démarche d'état civil et éprouve des difficultés à lire sur les lèvres en raison du port de masques ou de parois vitrées.","o":["Proposer immédiatement un échange par écrit sur bloc-notes ou support numérique, avec des phrases simples et claires.","Hausser la voix de plus en plus fort en criant à travers la vitre de protection.","Lui faire signe de la main de quitter les lieux et refuser de traiter sa demande.","Vérifier si un agent formé à la langue des signes est présent dans le service ou mobiliser le service de visio-interprétation de l'État."],"a":0,"e":"L'accessibilité des services publics aux personnes en situation de handicap exige de faire preuve d'adaptabilité, de bienveillance et d'ingéniosité (échange manuscrit, supports visuels, recours aux dispositifs de relais inclusifs).","r":[4,1,1,3],"x":["Très approprié : adaptation immédiate, respectueuse et efficace garantissant l'accessibilité universelle.","Très inapproprié : comportement inadapté et potentiellement humiliant n'apportant aucune aide à une personne sourde.","Très inapproprié : discrimination inacceptable et manquement intolérable aux obligations d'accueil.","Plutôt approprié : recours judicieux aux technologies et compétences inclusives mises en place par l'État."]},{"id":"situational-advise-035","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez chaque posture de conseil face à une omission déclarative constatée.","s":"Lors de la vérification d'un dossier de subvention d'une association, vous constatez qu'il manque un bilan d'activité obligatoire qui entraînerait le rejet automatique par la commission de demain.","o":["Contacter sans attendre le responsable associatif par téléphone et courriel pour lui permettre de transmettre la pièce manquante avant la clôture.","Laisser le dossier passer en commission en se réjouissant d'avance de son rejet automatique.","Rédiger un faux bilan d'activité à la place de l'association pour éviter tout retard d'instruction.","Informer le président de la commission de la démarche de régularisation engagée et solliciter un report bienveillant de l'examen."],"a":0,"e":"La bienveillance administrative encourage la régularisation proactive des omissions matérielles avant prise de décision définitive, tout en respectant strictement l'authenticité des pièces qui doivent émaner du seul déclarant.","r":[4,1,1,3],"x":["Très approprié : accompagnement proactif et bienveillant évitant un rejet préjudiciable sur simple oubli matériel.","Très inapproprié : cynisme et malveillance contraires à la mission d'appui aux usagers et au monde associatif.","Très inapproprié : falsification documentaire illégale constitutive d'un faux en écriture publique.","Plutôt approprié : transparence procédurale auprès de l'organe délibérant pour ménager une issue constructive."]}]};
/* QUESTION_BANK_END */
const state={route:"accueil",dark:false,session:null,answered:0,points:0,sessionCount:5},$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],names={accueil:"Vue d'ensemble",entrainement:"Entraînement",session:"Session",results:"Résultats",simulation:"Simulation",ressources:"Ressources",methode:"Méthode"};

/* All item text is escaped: question content is data, never markup. */
function esc(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function shuffle(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}return r}
function skillOf(x){return x.skill?` · ${esc(skillLabels[x.skill]||x.skill)}`:""}
function stimulusHtml(s){
  if(s==null)return"";
  if(typeof s==="string")return`<div class="stimulus text">${esc(s)}</div>`;
  if(s.type==="shapes")return`<div class="stimulus"><div class="shapes" role="img" aria-label="Série de figures">${esc(s.text)}</div></div>`;
  if(s.type==="table"){
    const head=`<tr>${s.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join("")}</tr>`;
    const body=s.rows.map(r=>`<tr>${r.map((c,i)=>i===0?`<th scope="row">${esc(c)}</th>`:`<td>${esc(typeof c==="number"?c.toLocaleString("fr-FR"):c)}</td>`).join("")}</tr>`).join("");
    return`<div class="stimulus"><table class="data">${s.caption?`<caption>${esc(s.caption)}</caption>`:""}<thead>${head}</thead><tbody>${body}</tbody></table>${s.note?`<p class="note">${esc(s.note)}</p>`:""}</div>`;
  }
  return"";
}
/* Options are shuffled once per question so the answer position carries no information. */
function prepare(x,m){const order=x.f==="tfcs"?x.o.map((_,i)=>i):shuffle(x.o.map((_,i)=>i));return{...x,m,o:order.map(i=>x.o[i]),r:x.r?order.map(i=>x.r[i]):null,x:x.x?order.map(i=>x.x[i]):null,a:order.indexOf(x.a)}}
function scoreRating(user,key){const gap=key.reduce((s,k,i)=>s+Math.abs(k-user[i]),0)/key.length;return Math.max(0,1-gap/3)}

function route(n){if(state.session&&!state.session.done&&!["session","results"].includes(n)){if(!confirm("Quitter cette session ?"))return;clearInterval(state.session.interval);state.session=null}state.route=n;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`v-${n}`));$$('[data-route]').forEach(b=>b.setAttribute('aria-current',b.dataset.route===n?'page':'false'));$('#crumb').textContent=names[n];history.replaceState(null,"",n==='accueil'?location.pathname:`#${n}`);scrollTo({top:0,behavior:'smooth'});if(n==='accueil')dashboard()}

function optionReview(t){
  const x=t.x,ans=t.ans;
  if(x.f==="rating"){
    return x.o.map((opt,i)=>{const u=ans&&ans.choice?ans.choice[i]:null,k=x.r[i],cls=u==null?"":Math.abs(u-k)<=0?" is-user-correct":Math.abs(u-k)===1?"":" is-user-wrong";
      return`<div class="review-opt${cls}${i===x.a?" is-target":""}"><span>${esc(opt)}${x.x?`<small class="why">${esc(x.x[i])}</small>`:""}</span><span class="review-tag ${u===k?"user correct":"target"}">Vous : ${u??"—"} · Réf. : ${k}</span></div>`}).join("");
  }
  return x.o.map((opt,i)=>{const isUser=ans&&ans.choice===i,isTarget=i===x.a;let cls="review-opt",tag="";
    if(isUser&&isTarget){cls+=" is-user-correct";tag='<span class="review-tag user correct">Votre choix (correct)</span>'}
    else if(isUser){cls+=" is-user-wrong";tag='<span class="review-tag user">Votre choix</span>'}
    else if(isTarget){cls+=" is-target";tag='<span class="review-tag target">Bonne réponse</span>'}
    return`<div class="${cls}"><span>${esc(opt)}${x.x?`<small class="why">${esc(x.x[i])}</small>`:""}</span>${tag}</div>`}).join("");
}
function renderReview(filter="all"){
  const s=state.session;if(!s)return;
  const items=s.questions.map((x,i)=>{const ans=s.answers[i];return{x,i,ans,isGood:Boolean(ans&&ans.good),isSkip:!ans||ans.choice===null}});
  const okCount=items.filter(t=>t.isGood).length;
  $('#review-filters').innerHTML=`<button type="button" data-filter="all" aria-pressed="${filter==='all'}">Toutes (${items.length})</button><button type="button" data-filter="ko" aria-pressed="${filter==='ko'}">À revoir (${items.length-okCount})</button><button type="button" data-filter="ok" aria-pressed="${filter==='ok'}">Réussies (${okCount})</button>`;
  $('#review-filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b)renderReview(b.dataset.filter)};
  const filtered=items.filter(t=>filter==='ok'?t.isGood:filter==='ko'?!t.isGood:true);
  if(!filtered.length){$('#review').innerHTML='<p class="lede" style="padding:var(--s4);text-align:center">Aucun élément dans cette catégorie.</p>';return}
  $('#review').innerHTML=filtered.map(t=>{const st=t.isGood?['is-good','ok','Correct']:t.isSkip?['is-skip','skipped','Passée']:['is-bad','ko','À revoir'];
    const pts=t.x.f==="rating"&&t.ans&&t.ans.choice?` · ${Math.round(t.ans.points*100)} %`:"";
    return`<details class="review-item ${st[0]}" ${filter==='ko'?'open':''}><summary class="review-summary"><div class="review-summary-left"><strong>#${t.i+1}</strong><span>${esc(modules[t.x.m].title)}${skillOf(t.x)}</span></div><span class="review-badge ${st[1]}">${st[2]}${pts}</span></summary><div class="review-detail"><h3 class="qprompt">${esc(t.x.p)}</h3>${stimulusHtml(t.x.s)}<div class="review-options">${optionReview(t)}</div><div class="feedback ${t.isGood?'good':'bad'}"><strong>Explication pédagogique</strong><p>${esc(t.x.e)}</p></div></div></details>`}).join('');
}

function start(type,countChoice){
  let questions,title,seconds,guided=true;
  const pick=(k,n)=>shuffle(q[k]||[]).slice(0,n).map(x=>prepare(x,k));
  const count=countChoice!==undefined?countChoice:state.sessionCount;
  if(type==='diagnostic'){questions=shuffle(Object.keys(modules).flatMap(k=>pick(k,2)));title='Diagnostic transversal';seconds=900}
  else if(type==='simulation'){questions=shuffle(Object.keys(modules).flatMap(k=>pick(k,3)));title='Simulation A1';seconds=1500;guided=false}
  else if(type==='examen'){return startExam()}
  else{
    const total=(q[type]||[]).length;
    const n=(count==='all'||Number(count)>=total)?total:(Number(count)||5);
    questions=pick(type,n);
    title=`${modules[type].title} · ${questions.length} questions`;
    const baseMins=modules[type].minutes||10;
    seconds=Math.max(180,Math.round(questions.length*(baseMins*60/(total||10))));
  }
  if(!questions.length)return;
  state.session={type,countChoice:count,questions,title,seconds,guided,index:0,answers:[],locked:false,done:false};
  $('#sessiontitle').textContent=title;$('#sessionkind').textContent=guided?'Entraînement guidé avec retour immédiat':'Simulation chronométrée (correction à la fin)';
  route('session');render();tick();
  state.session.interval=setInterval(()=>{state.session.seconds--;tick();if(state.session.seconds<=0)finish()},1000);
}
function startExam(){
  const sections=[],questions=[];
  for(const k of EXAM.sections){const qs=shuffle(q[k]||[]).slice(0,EXAM.questionsPerSection||Infinity).map(x=>prepare(x,k));if(!qs.length)continue;sections.push({cat:k,from:questions.length,to:questions.length+qs.length-1});questions.push(...qs)}
  if(!questions.length)return;
  state.session={type:'examen',questions,title:'Examen blanc A1 · 2 h',seconds:EXAM.minutesPerSection*60,guided:false,index:0,answers:[],locked:false,done:false,exam:{sections,current:0,waiting:true}};
  $('#sessiontitle').textContent=state.session.title;$('#sessionkind').textContent='Examen blanc : tests successifs chronométrés, correction à la fin';
  route('session');tick();sectionIntro();
}
function sectionIntro(){
  const s=state.session,e=s.exam,sec=e.sections[e.current],n=sec.to-sec.from+1;
  e.waiting=true;s.seconds=EXAM.minutesPerSection*60;tick();
  $('#position').textContent=`Test ${e.current+1} / ${e.sections.length}`;
  $('#sessionbar').style.setProperty('--value',`${(sec.from/s.questions.length)*100}%`);
  $('#question').innerHTML=`<p class="eyebrow">Test ${e.current+1} sur ${e.sections.length}</p><h2 class="qprompt">${esc(modules[sec.cat].title)}</h2><p class="lede">${n} questions · ${EXAM.minutesPerSection} minutes. Le chronomètre démarre quand vous commencez ; à la fin du temps, le test suivant s'ouvre et les questions non traitées comptent comme non répondues.</p><p class="lede">Le jour de l'épreuve, lisez les consignes et résolvez les exemples proposés au début de chaque test.</p><div class="actions"><button class="btn" id="startsection">Commencer le test</button></div>`;
  $('#startsection').onclick=()=>{e.waiting=false;s.index=sec.from;render();s.interval=setInterval(()=>{s.seconds--;tick();if(s.seconds<=0)endSection()},1000)};
}
function endSection(){
  const s=state.session;if(!s||!s.exam||s.done)return;
  clearInterval(s.interval);
  const e=s.exam,sec=e.sections[e.current];
  for(let i=sec.from;i<=sec.to;i++)if(!s.answers[i])s.answers[i]={choice:null,good:false,points:0};
  e.current++;
  if(e.current>=e.sections.length)return finish();
  s.index=e.sections[e.current].from;sectionIntro();
}
function tick(){const x=Math.max(0,state.session.seconds);$('#timer').textContent=`${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`;$('#timer').classList.toggle('low',x<60)}
function render(){
  const s=state.session,x=s.questions[s.index];s.locked=false;
  const sec=s.exam?s.exam.sections[s.exam.current]:null;
  $('#position').textContent=sec?`Test ${s.exam.current+1}/${s.exam.sections.length} · ${s.index-sec.from+1} / ${sec.to-sec.from+1}`:`${s.index+1} / ${s.questions.length}`;
  $('#sessionbar').style.setProperty('--value',`${(s.index/s.questions.length)*100}%`);
  let body;
  if(x.f==="rating"){
    body=`<p class="rating-help">Notez chaque réaction de 1 (très inapproprié) à 4 (très approprié).</p><div class="ratings">${x.o.map((z,i)=>`<fieldset class="rating-row" data-row="${i}"><legend>${esc(z)}</legend><div class="scale">${ratingLabels.map((l,v)=>`<label title="${l}"><input type="radio" name="r${i}" value="${v+1}"><span>${v+1}</span><small>${l}</small></label>`).join("")}</div><div class="rowfeedback"></div></fieldset>`).join("")}</div>`;
  }else{
    body=`<fieldset class="options${x.m==="abstract"?" figs":""}"><legend class="sr">Options de réponse</legend>${x.o.map((z,i)=>`<label class="option"><input type="radio" name="answer" value="${i}"><span>${esc(z)}</span></label>`).join('')}</fieldset>`;
  }
  $('#question').innerHTML=`<p class="eyebrow">${esc(modules[x.m].title)}${skillOf(x)}</p><h2 class="qprompt">${esc(x.p)}</h2>${stimulusHtml(x.s)}${body}<div id="feedback" role="status" aria-live="polite"></div><div class="actions"><button class="btn" id="validate">${s.guided?'Valider':'Réponse suivante'}</button><button class="btn ghost" id="pass">Passer</button>${sec?'<button class="btn secondary" id="endsection">Terminer ce test</button>':''}</div>`;
  $('#validate').onclick=submit;$('#pass').onclick=()=>record(null);
  if(sec)$('#endsection').onclick=()=>{if(confirm('Terminer ce test ? Les questions non traitées compteront comme non répondues.'))endSection()};
}
function submit(){
  const x=state.session.questions[state.session.index];
  if(x.f==="rating"){
    const vals=x.o.map((_,i)=>{const c=$(`input[name=r${i}]:checked`);return c?Number(c.value):null});
    if(vals.includes(null)){$('#feedback').innerHTML='<div class="feedback bad"><strong>Notation incomplète</strong>Notez chacune des réactions, ou passez la question.</div>';return}
    return record(vals);
  }
  const c=$('input[name=answer]:checked');
  if(!c){$('#feedback').innerHTML='<div class="feedback bad"><strong>Sélection requise</strong>Choisissez une option ou passez.</div>';return}
  record(Number(c.value));
}
function record(choice){
  const s=state.session;if(s.locked)return;s.locked=true;
  const x=s.questions[s.index];
  const points=choice===null?0:x.f==="rating"?scoreRating(choice,x.r):choice===x.a?1:0;
  const good=x.f==="rating"?points>=0.75:points===1;
  s.answers[s.index]={choice,good,points};
  if(choice!==null){state.answered++;state.points+=points}
  if(!s.guided||choice===null)return next();
  if(x.f==="rating"){
    $$('.rating-row').forEach((row,i)=>{row.querySelectorAll('input').forEach(inp=>inp.disabled=true);const u=choice[i],k=x.r[i];row.classList.add(u===k?'correct':Math.abs(u-k)===1?'near':'wrong');row.querySelector('.rowfeedback').textContent=`Votre note : ${u} · note de référence : ${k}${x.x?` — ${x.x[i]}`:""}`});
    $('#feedback').innerHTML=`<div class="feedback ${good?'good':'bad'}"><strong>${Math.round(points*100)} % de concordance</strong>${esc(x.e)}</div>`;
  }else{
    $$('.option').forEach((el,i)=>{if(i===x.a)el.classList.add('correct');if(i===choice&&choice!==x.a)el.classList.add('wrong');el.querySelector('input').disabled=true});
    $('#feedback').innerHTML=`<div class="feedback ${good?'good':'bad'}"><strong>${good?'Bonne réponse':'À revoir'}</strong>${esc(x.e)}${x.x&&choice!==x.a?`<p class="why">Votre choix : ${esc(x.x[choice])}</p>`:""}</div>`;
  }
  $('#validate').textContent=s.index===s.questions.length-1?'Voir le bilan':'Question suivante';$('#validate').onclick=next;$('#pass').disabled=true;
}
function next(){const s=state.session;if(s.exam&&s.index>=s.exam.sections[s.exam.current].to)return endSection();if(s.index<s.questions.length-1){s.index++;render()}else finish()}
function finish(){
  const s=state.session;if(!s||s.done)return;s.done=true;clearInterval(s.interval);
  const total=s.questions.length,pts=s.answers.reduce((n,a)=>n+(a?a.points:0),0),good=s.answers.filter(a=>a&&a.good).length,pct=Math.round(pts/total*100);
  $('#ring').style.setProperty('--score',`${pct}%`);$('#score').textContent=`${pct}%`;
  $('#message').textContent=pct>=80?'Très bonne maîtrise':pct>=60?'Base solide à consolider':'Analysez vos erreurs';
  $('#detail').textContent=`${good} question(s) réussie(s) sur ${total}. Les questions de jugement situationnel comptent selon la concordance de vos notes. Ce pourcentage n’est pas une note Stanine.`;
  if(s.exam){
    const rows=s.exam.sections.map(sec=>{const idx=[];for(let i=sec.from;i<=sec.to;i++)idx.push(i);const p=idx.reduce((n,i)=>n+(s.answers[i]?s.answers[i].points:0),0),done=idx.filter(i=>s.answers[i]&&s.answers[i].choice!==null).length;return{cat:sec.cat,pct:Math.round(p/idx.length*100),done,n:idx.length}});
    const avg=Math.round(rows.reduce((n,r)=>n+r.pct,0)/rows.length);
    $('#ring').style.setProperty('--score',`${avg}%`);$('#score').textContent=`${avg}%`;
    $('#message').textContent=avg>=80?'Très bonne maîtrise':avg>=60?'Base solide à consolider':'Analysez vos erreurs';
    $('#detail').innerHTML=`Moyenne des ${rows.length} tests (chacun compte autant, comme dans la notation officielle) : <strong>${avg} %</strong>. Ce n'est pas une note Stanine.<span class="sectionscores">${rows.map(r=>`<span class="row"><span>${esc(modules[r.cat].title)}</span><span>${r.pct} % · ${r.done}/${r.n} traitées</span></span>`).join('')}</span>`;
  }
  renderReview('all');$('#retry').onclick=()=>start(s.type,s.countChoice);route('results');
}
function dashboard(){const pct=state.answered?Math.round(state.points/state.answered*100):null;$('#accuracy').textContent=pct===null?'—':`${pct}%`;$('#homebar').style.setProperty('--value',`${pct||0}%`);$('#summary').textContent=state.answered?`${state.answered} question(s) répondue(s), questions passées non comptées.`:'Commencez un module pour établir votre diagnostic.'}
function theme(){document.documentElement.dataset.theme=state.dark?'dark':'light';$('#theme').innerHTML=state.dark?sun:moon;$('#theme').setAttribute('aria-label',`Passer au mode ${state.dark?'clair':'sombre'}`)}
function renderModules(){
  const cnt=state.sessionCount;
  $('#modules').innerHTML=Object.entries(modules).map(([k,m])=>{
    const total=(q[k]||[]).length;
    const drawText=cnt==='all'||Number(cnt)>=total?`${total} questions`:`${cnt} sur ${total} (tirage aléatoire)`;
    return `<button class="module" data-module="${k}"><span class="code">${m.code}</span><span class="count">${drawText}</span><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p></button>`;
  }).join('');
}
function init(){
  renderModules();
  $('#modules').onclick=e=>{const b=e.target.closest('[data-module]');if(b)start(b.dataset.module)};
  const picker=$('#session-picker');
  if(picker){
    picker.onclick=e=>{
      const chip=e.target.closest('.chip');
      if(!chip)return;
      state.sessionCount=chip.dataset.size==='all'?'all':Number(chip.dataset.size);
      $$('#session-picker .chip').forEach(c=>c.setAttribute('aria-pressed',c===chip?'true':'false'));
      renderModules();
    };
  }
  $$('[data-route]').forEach(b=>b.onclick=e=>{e.preventDefault();route(b.dataset.route)});
  $$('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));
  state.dark=matchMedia('(prefers-color-scheme:dark)').matches;theme();$('#theme').onclick=()=>{state.dark=!state.dark;theme()};
  const first=location.hash.slice(1);route(['entrainement','simulation','ressources','methode'].includes(first)?first:'accueil');
}
init();
